import type { BChap } from '../types';
const C: BChap[] = [{"v":["Ось імена синів Ізраїлевих, які ввійшли в Єгипет з Яковом [батьком їхнім], увійшли кожен з [усім] домом своїм:","Рувим, Симеон, Левій та Іуда,","Іссахар, Завулон і Веніамін,","Дан і Неффалим, Гад і Асир.","Усіх же душ, що народилися від стегон Якова, було сімдесят [п’ять], а Йосиф був уже в Єгипті.","І помер Йосиф і всі брати його і весь рід їх;","а сини Ізраїлеві розплодилися і розмножилися, і підросли і посилилися надзвичайно, і наповнилася ними земля та.","І став над Єгиптом новий цар, який не знав Йосифа,","і сказав народу своєму: ось, народ синів Ізраїлевих численний і сильніший за нас;","перехитруємо ж його, щоб він не розмножувався; інакше, коли станеться війна, з’єднається і він з нашими ворогами, і озброїться проти нас, і вийде з землі [нашої].","І поставили над ним начальників робіт, щоб виснажували його важкими роботами. І він побудував фараону Пифом і Раамсес, міста для запасів, [і Он, інакше Іліополь].","Але чим більше виснажували його, тим більше він примножувався і тим більше зростав, так що [єгиптяни] побоювалися синів Ізраїлевих.","І тому єгиптяни з жорстокістю силували синів Ізраїлевих до робіт","і робили життя їхнє гірким від важкої роботи над глиною і цеглою і від усякої роботи польової, від всякої роботи, до якої змушували їх з жорстокістю.","Цар Єгипетський повелів повитухам євреянок, з яких одній ім’я Шифра, а другій Фуа,","і сказав [їм]: коли ви будете повивати у євреянок, то спостерігайте при пологах: якщо буде син, то умертвляйте його, а якщо дочка, то нехай живе.","Але повитухи боялися Бога і не робили так, як говорив їм цар Єгипетський, і залишали дітей живими.","Цар Єгипетський покликав повитух і сказав їм: для чого ви робите таку справу, що залишаєте дітей живими?","Повитухи сказали фараонові: єврейські жінки не такі, як єгипетські; вони здорові, тому що перш ніж прийде до них повитуха, вони вже народжують.","За це Бог чинив добро повитухам, а народ розмножувався і дуже посилювався.","І оскільки повитухи боялися Бога, то Він утверджував доми їхні.","Тоді фараон усьому народові своєму повелів, говорячи: всякого новонародженого [у євреїв] сина кидайте в ріку, а всяку дочку залишайте живою."],"x":{"1":"0.46.8|54.7.15","2":"0.46.8|1.6.14","6":"0.50.26","7":"54.7.17|25.104.24","12":"25.104.24","13":"4.26.6|19.5.11","16":"29.18.5","21":"8.2.35","22":"29.18.5|54.7.19"}},{"v":["Хтось із племені Левіїного пішов і взяв собі дружину з того самого племені.","Дружина зачала і народила сина і, бачачи, що він дуже красивий, ховала його три місяці;","але не маючи можливости ховати його далі, взяла кошик з очерету й обсмолила його асфальтом і смолою і, поклавши в ньому дитину, поставила в очереті біля берега ріки,","а сестра його стала здаля спостерігати, що з ним буде.","І вийшла дочка фараонова на річку купатися, а служниці її ходили по березі ріки. Вона побачила кошик серед очерету і послала рабиню свою взяти його.","Відкрила і побачила немовля; і ось, немовля плаче [у кошику]; і зглянулася на нього [дочка фараонова] і сказала: це з єврейських дітей.","І сказала сестра його дочці фараоновій: чи не сходити мені і чи не покликати до тебе годувальницю з євреянок, щоб вона вигодувала тобі немовля?","Дочка фараонова сказала їй: сходи. Дівчина пішла і покликала матір немовляти.","Дочка фараонова сказала їй: візьми немовля це і вигодуй його мені; я дам тобі плату. Жінка взяла немовля і годувала його.","І виросло немовля, і вона привела його до дочки фараонової, і він був у неї замість сина, і нарекла ім’я йому: Мойсей, тому що, говорила вона, я з води вийняла його.","Минуло багато часу, коли Мойсей виріс, трапилося, що він вийшов до братів своїх [синів Ізраїлевих] і побачив тяжку роботу їхню; і побачив, що єгиптянин б’є одного єврея з братів його, [синів Ізраїлевих].","Подивившись туди й сюди і побачивши, що нема нікого, він убив єгиптянина і сховав його у піску.","І вийшов він на другий день, і ось, два євреї сваряться; і сказав він тому, хто кривдив: навіщо ти б’єш ближнього твого?","А той сказав: хто поставив тебе начальником і суддею над нами? чи не думаєш убити мене, як убив [учора] єгиптянина? Мойсей злякався і сказав: дійсно, дізналися про цю справу.","І почув фараон про цю справу і хотів убити Мойсея; але Мойсей утік від фараона й зупинився в землі Мадіамській; і [прийшовши в землю Мадіамську], сів біля колодязя.","У священика мадіамського [було] сім дочок, [які пасли овець батька свого Іофора]. Вони прийшли, набрали води і наповнили корита, щоб напоїти овець батька свого [Іофора].","І прийшли пастухи і відігнали їх. Тоді встав Мойсей і захистив їх, [і начерпав їм води] і напоїв овець їхніх.","І прийшли вони до Рагуїла, батька свого, і він сказав [їм]: чому ви так скоро прийшли сьогодні?","Вони сказали: якийсь єгиптянин захистив нас від пастухів і навіть начерпав нам води і напоїв овець [наших].","Він сказав дочкам своїм: де ж він? навіщо ви залишили його? покличте його, і нехай він їсть хліб.","Мойсеєві сподобалося жити у цього чоловіка; і він видав за Мойсея дочку свою Сепфору.","Вона [зачала і] народила сина, і [Мойсей] нарік йому ім’я: Гирсам, тому що, говорив він, я став пришельцем у чужій землі. [І, зачавши ще, народила другого сина, і він нарік йому ім’я Єлиєзер, сказавши: Бог отця мого був мені помічником і визволив мене від руки фараона.]","Минув довгий час, помер цар Єгипетський. І стогнали сини Ізраїлеві від роботи і волали, і волання їхнє від роботи дійшло до Бога.","І почув Бог стогін їх, і згадав Бог завіт Свій з Авраамом, Ісааком і Яковом.","І побачив Бог синів Ізраїлевих, і споглянув на них Бог."],"x":{"2":"1.6.20|3.26.59|12.23.13|54.7.20|75.11.23","3":"29.18.5","5":"54.7.21","11":"75.11.24-25","12":"54.7.24","14":"54.7.27","15":"54.7.29|0.29.2","17":"0.24.13|0.29.8:10","18":"3.10.29","21":"1.18.2|3.12.1","22":"1.18.3|12.23.15|54.7.29","23":"1.7.7","24":"0.15.16|2.26.42"}},{"v":["Мойсей пас овець у Іофора, тестя свого, священика мадіамського. Одного разу провів він отару далеко в пустелю і прийшов до гори Божої, Хорива.","І явився йому ангел Господній у полум’ї вогню з середини тернового куща. І побачив він, що терновий кущ горить вогнем, але кущ не згорає.","Мойсей сказав: піду і подивлюся на це велике явлення, чому кущ не згорає.","Господь побачив, що він іде дивитися, і звернувся до нього Бог із середини куща, і сказав: Мойсею! Мойсею! Він сказав: ось я, [Господи]!","І сказав Бог: не підходь сюди; зніми взуття твоє з ніг твоїх, тому що місце, на якому ти стоїш, є земля свята.","І сказав [йому]: Я Бог батька твого, Бог Авраама, Бог Ісаака і Бог Якова. Мойсей закрив лице своє, тому що боявся дивитися на Бога.","І сказав Господь [Мойсеєві]: Я бачив страждання народу Мого в Єгипті і почув волання його від приставників його; Я знаю скорботи його","і йду визволити його від руки єгиптян і вивести його з землі цієї [і ввести його] у землю добру і простору, де тече молоко і мед, у землю хананеїв, хеттеїв, аморреїв, ферезеїв, [гергесеїв,] евеїв та ієвусеїв.","І ось, уже волання синів Ізраїлевих дійшло до Мене, і Я бачу утиски, якими пригнічують їх єгиптяни.","Отже, піди: Я пошлю тебе до фараона [царя Єгипетського]; і виведи із Єгипту народ Мій, синів Ізраїлевих.","Мойсей сказав Богу: хто я, щоб мені йти до фараона [царя Єгипетського] і вивести з Єгипту синів Ізраїлевих?","І сказав [Бог]: Я буду з тобою, і ось тобі знамення, що Я послав тебе: коли ти виведеш народ [Мій] з Єгипту, ви завершите служіння Богу на цій горі.","І сказав Мойсей Богу: ось, я прийду до синів Ізраїлевих і скажу їм: Бог батьків ваших послав мене до вас. А вони скажуть мені: як Його ім’я? Що сказати мені їм?","Бог сказав Мойсеєві: Я є Сущий. І сказав: так скажи синам Ізраїлевим: Сущий [Ієгова] послав мене до вас.","І сказав ще Бог Мойсеєві: так скажи синам Ізраїлевим: Господь, Бог батьків ваших, Бог Авраама, Бог Ісаака і Бог Якова послав мене до вас. Ось ім’я Моє навіки, і пам’ять про Мене з роду в рід.","Піди, збери старійшин [синів] Ізраїлевим і скажи їм: Господь, Бог батьків ваших, явився мені, Бог Авраама, [Бог] Ісаака і [Бог] Якова, і сказав: Я відвідав вас і побачив, що чинять з вами в Єгипті.","І сказав: Я виведу вас від рабства єгипетського в землю хананеїв, хеттеїв, аморреїв, ферезеїв, [гергесеїв,] евеїв та ієвусеїв, у землю, де тече молоко і мед.","І вони послухають голосу твого, і підеш ти і старійшини Ізраїлеві до [фараона] царя Єгипетського, і скажете йому: Господь, Бог євреїв, прикликав нас; отже, відпусти нас у пустелю, на три дні шляху, щоб принести жертву Господу, Богу нашому.","Але Я знаю, що [фараон] цар Єгипетський не дозволить вам іти, якщо не примусити його рукою міцною;","і простягну руку Мою й уражу Єгипет усіма чудесами Моїми, які сотворю серед нього; і після того він відпустить вас.","І дам народу цьому милість в очах єгиптян; і коли підете, то підете не з порожніми руками:","кожна жінка випросить у сусідки своєї і в тієї, що живе в домі її, речей срібних і речей золотих, і одягу, і ви нарядите в них і синів ваших і дочок ваших, і обберете єгиптян."],"x":{"2":"54.7.30","4":"30.45.5","5":"5.5.15","6":"50.22.32|51.12.26|52.20.37","7":"3.20.16","10":"25.104.26","14":"76.1.4:8","15":"31.42.8|38.12.5|25.101.13","18":"1.5.1:3|1.8.1:27","20":"29.10.15|25.104.27","21":"1.11.3","22":"1.12.35"}},{"v":["І відповів Мойсей і сказав: а якщо вони не повірять мені і не послухають голосу мого і скажуть: не явився тобі Господь? [що сказати їм?]","І сказав йому Господь: що це в руці у тебе? Він відповів: жезл.","Господь сказав: кинь його на землю. Він кинув його на землю, і жезл перетворився на змія, і Мойсей побіг від нього.","І сказав Господь Мойсею: простягни руку твою і візьми його за хвіст. Він простяг руку свою, і взяв його [за хвіст]; і він став жезлом у руці його.","Це для того, щоб повірили [тобі], що явився тобі Господь, Бог батьків їх, Бог Авраама, Бог Ісаака і Бог Якова.","Ще сказав йому Господь: поклади руку твою до себе в пазуху. І він поклав руку свою до себе в пазуху, вийняв її [із пазухи своєї], і ось, рука його побіліла від прокази, як сніг.","[Ще] сказав [йому Господь]: поклади знову руку твою до себе в пазуху. І він поклав руку свою до себе в пазуху; і вийняв її з пазухи своєї, і ось, вона знову стала такою ж, як тіло його.","Якщо вони не повірять тобі і не послухають голосу першого знамення, то повірять голосу знамення іншого;","якщо ж не повірять і двом цим знаменням і не послухають голосу твого, то візьми води з ріки і вилий на сушу; і вода, взята з річки, зробиться кров’ю на суші.","І сказав Мойсей Господу: о, Господи! людина я не красномовна, і таким був і вчора і третього дня, і коли Ти почав говорити з рабом Твоїм: я тяжко говорю і недорікуватий.","Господь сказав [Мойсеєві]: хто дав уста людині? хто робить німим, або глухим, або зрячим, або сліпим? чи не Я Господь [Бог]?","отже, піди, і Я буду при вустах твоїх і навчу тебе, що тобі говорити.","[Мойсей] сказав: Господи! пошли іншого, кого можеш послати.","І запалав гнів Господній на Мойсея, і Він сказав: хіба немає у тебе Аарона брата, левитянина? Я знаю, що він може говорити [замість тебе], і ось, він вийде назустріч тобі, і, побачивши тебе, зрадіє в серці своєму;","ти будеш йому говорити і вкладати слова [Мої] у вуста його, а Я буду при вустах твоїх і при вустах його і буду вчити вас, що вам робити;","і буде говорити він замість тебе до народу; отже, він буде твоїми вустами, а ти будеш йому замість Бога;","і жезл цей [який був перетворений на змія] візьми в руку твою: ним ти будеш творити знамення.","І пішов Мойсей, і повернувся до Іофора, тестя свого, і сказав йому: піду я, і повернуся до братів моїх, які в Єгипті, і подивлюся, чи живі ще вони? І сказав Іофор Мойсеєві: йди з миром. [Через багато часу помер цар Єгипетський.]","І сказав Господь Мойсеєві в [землі] Мадіамській: піди, повернись у Єгипет, тому що померли всі, що шукали душі твоєї.","І взяв Мойсей дружину свою і синів своїх, посадив їх на осла і вирушив у землю Єгипетську. І жезл Божий Мойсей взяв у руку свою.","І сказав Господь Мойсею: коли підеш і повернешся в Єгипет, дивись, усі чудеса, які Я доручив тобі, зроби перед лицем фараона, а Я озлоблю серце його, і він не відпустить народ.","І скажи фараонові: так говорить Господь [Бог єврейський]: Ізраїль є син Мій, первісток Мій;","Я говорю тобі: відпусти сина Мого, щоб він звершив Мені служіння; а якщо не відпустиш його, то ось, Я уб’ю сина твого, первістка твого.","Дорогою на ночівлі трапилося, що зустрів його Господь і хотів умертвити його.","Тоді Сепфора, узявши кам’яний ніж, обрізала крайню плоть сина свого і, кинувши до ніг його, сказала: ти наречений крови у мене.","І відійшов від нього Господь. Тоді сказала вона: наречений крови — за обрізанням.","І Господь сказав Аарону: піди назустріч Мойсеєві в пустелю. І він пішов, і зустрівся з ним біля гори Божої, і поцілував його.","І переказав Мойсей Аарону всі слова Господа, Який його послав, і всі знамення, що Він заповідав.","І пішов Мойсей з Аароном, і зібрали вони всіх старійшин синів Ізраїлевих,","і переказав [їм] Аарон усі слова, які говорив Господь Мойсеєві; і зробив Мойсей знамення перед очима народу,","і повірив народ; і почули, що Господь відвідав синів Ізраїлевих і побачив страждання їх, і схилилися вони і поклонилися."],"x":{"3":"1.7.10:15","5":"10.18.36","6":"3.12.10","9":"1.7.17:19|25.77.44","10":"1.6.12|31.6.5","11":"25.93.9","12":"50.10.19-20|52.21.15","15":"1.7.2|30.45.3","17":"1.4.3","18":"0.30.25","19":"0.31.3|50.2.20","21":"62.9.18","22":"32.31.9","23":"1.11.5|1.12.29","25":"5.5.2-3","27":"1.3.1","29":"5.24.5|25.104.26"}},{"v":["Після цього Мойсей і Аарон прийшли до фараона і сказали [йому]: так говорить Господь, Бог Ізраїлів: відпусти народ Мій, щоб він звершив Мені свято в пустелі.","Але фараон сказав: хто такий Господь, щоб я послухався голосу Його і відпустив [синів] Ізраїля? я не знаю Господа й Ізраїля не відпущу.","Вони сказали [йому]: Бог євреїв покликав нас; відпусти нас у пустелю на три дні шляху принести жертву Господу, Богу нашому, щоб Він не уразив нас моровицею, або мечем.","І сказав їм цар Єгипетський: для чого ви, Мойсей і Аарон, відволікаєте народ [мій] від справ його? ідіть [кожен з вас] на свою роботу.","І сказав фараон: ось, народ у землі цій численний, і ви відволікаєте його від роботи його.","І в той же день фараон дав повеління приставникам над народом і наглядачам, говорячи:","не давайте надалі народу соломи для вироблення цегли, як учора і третього дня, нехай вони самі ходять і збирають собі солому,","а цеглин накладіть на них ту саму визначену кількість, яку вони виробляли вчора і третього дня, і не зменшуйте; вони бездіяльні, тому і кричать: підемо, принесемо жертву Богу нашому;","дати їм більше роботи, щоб вони працювали і не займалися пустими речами.","І вийшли приставники народу і наглядачі його і сказали народу: так говорить фараон: не даю вам соломи;","самі підіть, беріть собі солому, де знайдете, а робота ваша ніскільки не зменшується.","І розсіявся народ по всій землі Єгипетській збирати жниво замість соломи.","Приставники ж примушували [їх], говорячи: виконуйте [визначену] роботу свою щодня, як і тоді, коли була у вас солома.","А наглядачів із синів Ізраїлевих, яких поставили над ними приставники фараонові, били, говорячи: чому ви вчора і сьогодні не виготовляєте визначеної кількости цеглин, як було до цих пір?","І прийшли наглядачі синів Ізраїлевих і волали до фараона, говорячи: для чого ти так чиниш з рабами твоїми?","соломи не дають рабам твоїм, а цеглу говорять нам, робіть. І ось, рабів твоїх б’ють; гріх народу твоєму.","Але він сказав [їм]: бездіяльні ви, бездіяльні, тому і говорите: підемо, принесемо жертву Господу.","Ідіть же, працюйте; соломи не дадуть вам, а визначену кількість цегли давайте.","І побачили наглядачі синів Ізраїлевих біду свою в словах: не зменшуйте кількости цегли, яку [визначено] на кожен день.","І коли вони вийшли від фараона, то зустрілися з Мойсеєм і Аароном, які стояли, чекаючи на них,","і сказали їм: нехай бачить і судить вас Господь за те, що ви зробили нас ненависними в очах фараона і рабів його і дали їм меч у руки, щоб убити нас.","І звернувся Мойсей до Господа і сказав: Господи! для чого Ти піддав такій біді народ цей, [і] для чого послав мене?","бо з того часу, як я прийшов до фараона і став говорити ім’ям Твоїм, він почав гірше чинити з народом цим; визволити ж, — Ти не визволив народ Твій."],"x":{"1":"1.7.16|1.8.1:20","2":"24.21.15|25.11.5|37.3.15","3":"1.3.18","5":"1.1.7","21":"0.34.30|8.13.4"}},{"v":["І сказав Господь Мойсеєві: тепер побачиш ти, що Я зроблю з фараоном; після дії руки міцної він відпустить їх; після дії руки міцної навіть вижене їх із землі своєї.","І говорив Бог Мойсею і сказав йому: Я Господь.","Являвся Я Аврааму, Ісааку і Якову з ім’ям «Бог Всемогутній», а з ім’ям Моїм «Господь»* не відкрився їм;","і Я поставив завіт Мій з ними, щоб дати їм землю Ханаанську, землю подорожування їх, по якій вони подорожували.","І Я почув стогін синів Ізраїлевих про те, що єгиптяни тримають їх у рабстві, і згадав завіт Мій.","Отже, скажи синам Ізраїлевим: Я Господь, і виведу вас з-під ярма єгиптян, і визволю вас від рабства їх, і врятую вас рукою простягнутою і судами великими;","і прийму вас Собі в народ і буду вам Богом, і ви дізнаєтеся, що Я Господь, Бог ваш, Який вивів вас [із землі Єгипетської] з-під ярма єгипетського;","і введу вас у ту землю, про яку Я, піднявши руку Мою, клявся дати її Аврааму, Ісааку і Якову, і дам вам її у спадщину. Я Господь.","Мойсей переказав це синам Ізраїлевим; але вони не послухали Мойсея через легкодухість і тяжку роботу.","І сказав Господь Мойсею, говорячи:","ввійди, скажи фараону, царю Єгипетському, щоб він відпустив синів Ізраїлевих із землі своєї.","І сказав Мойсей перед Господом, говорячи: ось, сини Ізраїлеві не слухають мене; як же послухає мене фараон? а я некрасномовний.","І говорив Господь Мойсеєві й Аарону, і давав їм повеління до синів Ізраїлевих і до фараона, царя Єгипетського, щоб вивести синів Ізраїлевих із землі Єгипетської.","Ось начальники поколінь їх: сини Рувима, первістка Ізраїлевого: Ханох і Фаллу, Хецрон і Хармі: це сімейства Рувимові.","Сини Симеона: Іємуїл та Іамин, і Огад, й Іахин, і Цохар, і Саул, син хананеянки: це сімейства Симеона.","Ось імена синів Левія за родами їх: Гирсон і Кааф і Мерарі. А років життя Левія було сто тридцять сім.","Сини Гирсона: Ливні і Шимеї з сімействами їх.","Сини Каафові: Амрам та Іцгар, і Хеврон, і Узиїл. А років життя Каафа було сто тридцять три роки.","Сини Мерарі: Махли і Муши. Це сімейства Левія за родами їх.","Амрам узяв Іохаведу, тітку свою, собі за дружину, і вона народила йому Аарона і Мойсея [і Маріам, сестру їх]. А років життя Амрама було сто тридцять сім.","Сини Іцгарові: Корей і Нефег і Зихрі.","Сини Узиїлові: Мисаїл і Елцафан і Сифрі.","Аарон узяв собі за дружину Єлизавету, дочку Аминадава, сестру Наассона, і вона народила йому Надава й Авиуда, Єлеазара та Іфамара.","Сини Корея: Асир, Елкана й Авиасаф: це сімейства Кореєві.","Єлеазар, син Аарона, узяв собі за дружину одну з дочок Футиїлових, і вона народила йому Финеєса. Ось начальники поколінь левитських за родинами їх.","Аарон і Мойсей, це — ті, яким сказав Господь: виведіть синів Ізраїлевих із землі Єгипетської за ополченнями їх.","Вони-то говорили фараонові, царю Єгипетському, щоб вивести синів Ізраїлевих з Єгипту; це — Мойсей і Аарон.","Отже, в той час, коли Господь говорив Мойсеєві в землі Єгипетській,","Господь сказав Мойсеєві, говорячи: Я Господь! скажи фараонові, царю Єгипетському, все, що Я говорю тобі.","Мойсей же сказав перед Господом: ось, я некрасномовний: як же послухає мене фараон?"],"x":{"1":"1.11.1|1.12.33|1.13.3","2":"1.15.3","3":"0.17.1|0.26.24|0.28.13","5":"1.2.24|2.26.42","7":"0.17.7","8":"36.47.14","12":"1.4.10|31.6.5","14":"0.46.9|3.26.5|12.5.1:3","15":"12.4.24","16":"12.6.1|3.3.17|3.26.57","17":"3.3.18|12.6.17","18":"3.3.19","19":"3.26.57","20":"1.2.1-2|3.26.59|12.6.3|54.7.20|75.11.23","21":"3.16.1","22":"2.10.4","23":"3.3.2","24":"12.6.22","25":"3.25.7|12.6.4","26":"54.7.37","30":"1.4.10|1.6.12"},"n":{"3":["Ієгова."]}},{"v":["Але Господь сказав Мойсеєві: дивись, Я поставив тебе Богом фараону, а Аарон, брат твій, буде твоїм пророком:","ти будеш говорити [йому] усе, що Я повелю тобі, а Аарон, брат твій, буде говорити фараону, щоб він відпустив синів Ізраїлевих із землі своєї;","але Я озлоблю серце фараонове, і явлю багато знамень Моїх і чудес Моїх у землі Єгипетській;","фараон не послухає вас, і Я накладу руку Мою на Єгипет і виведу воїнство Моє, народ Мій, синів Ізраїлевих, із землі Єгипетської — судами великими;","тоді довідаються [усі] єгиптяни, що Я Господь, коли простягну руку Мою на Єгипет і виведу синів Ізраїлевих із середовища їх.","І зробили Мойсей і Аарон, як повелів їм Господь, так вони і зробили.","Мойсей був вісімдесяти, а Аарон [брат його] вісімдесяти трьох років, коли вони почали говорити до фараона.","І сказав Господь Мойсеєві й Ааронові, говорячи:","якщо фараон скаже вам: зробіть [знамення або] чудо, то ти скажи Аарону [братові твоєму]: візьми жезл твій і кинь [на землю] перед фараоном [і перед рабами його], — він стане змієм.","Мойсей і Аарон прийшли до фараона [і до рабів його] і зробили так, як повелів [їм] Господь. І кинув Аарон жезл свій перед фараоном і перед рабами його, і він зробився змієм.","І покликав фараон мудреців [єгипетських] і чарівників; і ці волхви єгипетські зробили те саме своїми чарами:","кожен з них кинув свій жезл, і вони зробилися зміями, але жезл Ааронів поглинув їхні жезли.","Серце фараонове озлобилося, і він не послухав їх, як і говорив [їм] Господь.","І сказав Господь Мойсеєві: вперте серце фараонове: він не хоче відпустити народ.","Піди до фараона завтра: ось, він вийде до води, ти стань на шляху його, на березі ріки, і жезл, що перетворювався на змія, візьми в руку твою","і скажи йому: Господь, Бог євреїв, послав мене сказати тобі: відпусти народ Мій, щоб він звершив Мені служіння в пустелі; але ось, ти до цих пір не послухався.","Так говорить Господь: із цього дізнаєшся, що Я Господь: ось цим жезлом, що в руці моїй, я вдарю по воді, що у ріці, і вона перетвориться на кров,","і риба в ріці вмре, і ріка засмердить, і єгиптянам гидко буде пити воду з ріки.","І сказав Господь Мойсею: скажи Аарону [братові твоєму]: візьми жезл твій [у руку твою] і простягни руку твою на води єгиптян: на ріки їх, на потоки їх, на озера їх і на усяке вмістилище вод їх, — і перетворяться на кров, і буде кров по всій землі Єгипетській і в дерев’яних і в кам’яних посудинах.","І зробили Мойсей і Аарон, як повелів [їм] Господь. І підняв [Аарон] жезл [свій] і вдарив по воді річковій перед очима фараона і перед очима рабів його, і вся вода в ріці перетворилася на кров,","і риба в ріці вимерла, й ріка засмерділа, і єгиптяни не могли пити води з ріки; і була кров по всій землі Єгипетській.","І волхви єгипетські чарами своїми зробили те саме. І озлобилося серце фараона, і не послухав їх, як і говорив Господь.","І обернувся фараон, і пішов у дім свій; і серце його не пом’якшало і через це.","І стали копати усі єгиптяни біля ріки, щоб знайти воду для пиття, тому що не могли пити води з ріки.","І виповнилося сім днів після того, як Господь уразив ріку."],"x":{"1":"1.4.15-16","3":"1.4.21|1.14.4","4":"1.6.6|1.8.15:19","6":"5.24.5","8":"1.9.8|1.12.1|4.4.33","9":"25.104.27","10":"1.4.3","11":"72.3.8","13":"8.6.6|1.4.21","14":"8.6.6","16":"1.5.1|1.8.1:20","17":"1.4.9","19":"1.8.5","20":"1.17.5|25.77.44","22":"29.17.7"}},{"v":["І сказав Господь Мойсеєві: піди до фараона і скажи йому: так говорить Господь: відпусти народ Мій, щоб він звершив Мені служіння;","якщо ж ти не погодишся відпустити, то ось, Я уражаю всю область твою жабами;","і закишить ріка жабами, і вони вийдуть і ввійдуть у дім твій, і в спальню твою, і на постіль твою, і в доми рабів твоїх і народу твого, і в печі твої, й у діжі твої,","і на тебе, і на народ твій, і на всіх рабів твоїх зійдуть жаби.","І сказав Господь Мойсею: скажи Аарону [братові твоєму]: простягни руку твою з жезлом твоїм на ріки, на потоки і на озера і виведи жаб на землю Єгипетську.","Аарон простяг руку свою на води єгипетські [і вивів жаб]; і вийшли жаби і покрили землю Єгипетську.","Те саме зробили і волхви [єгипетські] чарами своїми і вивели жаб на землю Єгипетську.","І покликав фараон Мойсея й Аарона і сказав: помоліться [за мене] Господу, щоб Він видалив жаб від мене і від народу мого, і я відпущу народ ізраїльський принести жертву Господу.","Мойсей сказав фараонові: признач мені сам, коли помолитися за тебе, за рабів твоїх і за народ твій, щоб жаби зникли в тебе, [у народу твого,] у домах твоїх, і залишилися тільки в ріці.","Він сказав: завтра. Мойсей відповів: буде за словом твоїм, щоб ти дізнався, що нема нікого, як Господь Бог наш;","і зникнуть жаби від тебе, від домів твоїх [і з полів], і від рабів твоїх і від твого народу; тільки в ріці вони залишаться.","Мойсей і Аарон вийшли від фараона, і Мойсей помолився до Господа про жаб, яких Він навів на фараона.","І вчинив Господь за словом Мойсея: жаби вимерли в домах, у дворах і на полях [їх];","і зібрали їх у купи, і засмерділа земля.","І побачив фараон, що зробилося полегшення, і озлобив серце своє, і не послухав їх, як і говорив Господь.","І сказав Господь Мойсеєві: скажи Аарону: простягни [рукою] жезл твій і вдар у порох земний, і [будуть мошки на людях і на худобі і на фараоні, і в домі його і на рабах його, весь порох земний] зробиться мошками по всій землі Єгипетській.","Так вони і зробили: Аарон простяг руку свою з жезлом своїм і вдарив у порох земний, і з’явились мошки на людях і на худобі. Весь порох земний зробився мошками по всій землі Єгипетській.","Намагалися також і волхви чарами своїми викликати мошок, але не могли. І були мошки на людях і на худобі.","І сказали волхви фараонові: це перст Божий. Але серце фараонове озлобилося, і він не послухав їх, як і говорив Господь.","І сказав Господь Мойсеєві: завтра встань рано і з’явися перед лице фараона. Ось, він піде до води, і ти скажи йому: так говорить Господь: відпусти народ Мій, щоб він звершив Мені служіння [у пустелі];","а якщо не відпустиш народу Мого, то ось, Я пошлю на тебе і на рабів твоїх, і на народ твій, і в доми твої песячих мух, і наповняться доми єгиптян песячими мухами і сама земля, на якій вони живуть;","і відділю в той день землю Гесем, на якій перебуває народ Мій, і там не буде песячих мух, щоб ти знав, що Я Господь [Бог] серед [усієї] землі;","Я зроблю поділ між народом Моїм і між народом твоїм. Завтра буде це знамення [на землі].","Так і зробив Господь: налетіло безліч песячих мух у дім фараонів, і в доми рабів його, і на всю землю Єгипетську: гинула земля від песячих мух.","І покликав фараон Мойсея й Аарона і сказав: підіть, принесіть жертву [Господу] Богу вашому в цій землі.","Але Мойсей сказав: не можна цього зробити, бо огидне для єгиптян жертвоприношення наше Господу, Богу нашому: якщо ми огидну для єгиптян жертву станемо приносити на очах їхніх, то чи не поб’ють вони нас камінням?","ми підемо в пустелю, на три дні шляху, і принесемо жертву Господу, Богу нашому, як скаже нам [Господь].","І сказав фараон: я відпущу вас принести жертву Господу Богу вашому в пустелі, тільки не йдіть далеко; помоліться за мене [Господу].","Мойсей сказав: ось, я виходжу від тебе і помолюсь Господу [Богу], і зникнуть песячі мухи від фараона, і від рабів його, і від народу його завтра, тільки фараон нехай перестане обманювати, не відпускаючи народ принести жертву Господу.","І вийшов Мойсей від фараона і помолився Господу.","І зробив Господь за словом Мойсея і відігнав песячих мух від фараона, від рабів його і від народу його: не залишилося жодної.","Але фараон озлобив серце своє і цього разу і не відпустив народ."],"x":{"1":"1.5.1|1.7.16","5":"1.7.19","6":"25.77.45|25.104.30","7":"29.17.7","8":"1.10.16|10.13.6","10":"1.9.14|1.15.11","15":"62.2.4-5|1.4.21","17":"25.104.31","19":"25.63.10|50.12.28|52.11.20","22":"1.9.26","24":"25.104.31|29.16.9","26":"0.43.32|0.46.34","27":"1.3.18","28":"10.13.6|54.8.24","31":"1.10.19|1.14.28"}},{"v":["І сказав Господь Мойсеєві: піди до фараона і скажи йому: так говорить Господь, Бог євреїв: відпусти народ Мій, щоб він звершив Мені служіння;","бо якщо ти не захочеш відпустити [народ Мій] і ще будеш утримувати його,","то ось, рука Господня буде на худобі твоїй, яка у полі, на конях, на ослах, на верблюдах, на волах і вівцях: буде моровиця дуже тяжка;","і розділить Господь [у той час] худобу ізраїльську і худобу єгипетську, і з усієї [худоби] синів Ізраїлевих не помре нічого.","І призначив Господь час, сказавши: завтра зробить це Господь у землі цій.","І зробив це Господь на другий день, і вимерла вся худоба єгипетська; з худоби ж синів Ізраїлевих не померло нічого.","Фараон послав дізнатися, і ось, з [усієї] худоби [синів] Ізраїлевих не померло нічого. Але серце фараонове озлобилося, і він не відпустив народ.","І сказав Господь Мойсеєві й Аарону: візьміть по повній жмені попелу з печі, і нехай кине його Мойсей до неба на очах фараона [і рабів його];","і здійметься курява по всій землі Єгипетській, і буде на людях і на худобі запалення з наривами, в усій землі Єгипетській.","Вони взяли попіл з печі і постали перед лицем фараона. Мойсей кинув його до неба, і зробилося запалення з наривами на людях і на худобі.","І не могли волхви устояти перед Мойсеєм через запалення, тому що запалення було на волхвах і на всіх єгиптянах.","Але Господь озлобив серце фараона, і він не послухав їх, як і говорив Господь Мойсеєві.","І сказав Господь Мойсеєві: завтра встань рано і з’явися перед лице фараона, і скажи йому: так говорить Господь, Бог євреїв: відпусти народ Мій, щоб він звершив Мені служіння;","бо цього разу Я пошлю всі виразки Мої в серце твоє, і на рабів твоїх, і на народ твій, щоб ти дізнався, що немає подібного до Мене на всій землі;","якби Я простяг руку Мою, то вразив би тебе і народ твій виразкою, і ти знищений був би на землі:","але для того Я зберіг тебе, щоб показати на тобі силу Мою, і щоб сповіщено було ім’я Моє по всій землі;","ти ще протистоїш народу Моєму, щоб не відпускати його, —","ось, Я пошлю завтра, у цей самий час, град дуже сильний, якому подібного не було в Єгипті з дня заснування його донині;","отже, пошли зібрати отари твої й усе, що є в тебе в полі: на всіх людей і худобу, що залишаться в полі і не зберуться в домах, упаде град, і вони помруть.","Ті з рабів фараонових, які убоялися слова Господнього, поспіхом зібрали рабів своїх і отари свої в доми;","а хто не звернув серця свого до слів Господа, той залишив рабів своїх і отари свої в полі.","І сказав Господь Мойсеєві: простягни руку твою до неба, й упаде град на всю землю Єгипетську, на людей, на худобу і на всю траву польову в землі Єгипетській.","І простяг Мойсей жезл свій до неба, і Господь зробив грім і град, і вогонь розливався по землі; і послав Господь град на [всю] землю Єгипетську;","і був град і вогонь між градом, [град] дуже сильний, якого не було у всій землі Єгипетській з часу заселення її.","І побив град по всій землі Єгипетській усе, що було в полі, від людини до худоби, і всю траву польову побив град, і всі дерева в полі поламав [град];","тільки в землі Гесем, де жили сини Ізраїлеві, не було граду.","І послав фараон, і покликав Мойсея й Аарона, і сказав їм: цього разу я згрішив; Господь праведний, а я і народ мій винні;","помоліться [за мене] Господу: нехай припиняться громи Божі і град [і вогонь на землі], і відпущу вас і не буду більше затримувати.","Мойсей сказав йому: як тільки я вийду з міста, простягну руки мої до Господа [на небо], громи припиняться, і граду [і дощу] більше не буде, щоб ти пізнав, що Господня земля;","але я знаю, що ти і раби твої ще не убоїтесь Господа Бога.","Льон і ячмінь були побиті, тому що ячмінь виколосився, а льон засеменився;","а пшениця і жито не побиті, тому що вони були пізні.","І вийшов Мойсей від фараона із міста і простяг руки свої до Господа, і припинилися грім і град, і дощ перестав литися на землю.","І побачив фараон, що перестав дощ і град і грім, і продовжував грішити, і обтяжив серце своє сам і раби його.","І озлобилося серце фараона [і рабів його], і він не відпустив синів Ізраїлевих, як і говорив Господь через Мойсея."],"x":{"1":"1.5.1|1.7.16|1.10.3","3":"4.2.15|25.77.50","7":"1.7.14|1.8.15:32","8":"1.7.8","11":"29.17.7","12":"1.4.21|1.8.15","16":"62.9.17","23":"25.77.47-48|25.104.32|29.16.16|29.19.19","27":"1.10.16|33.1.18","29":"25.23.1"}},{"v":["І сказав Господь Мойсеєві: ввійди до фараона, бо Я обтяжив серце його і серце рабів його, щоб явити між ними ці знамення Мої,","і щоб ти розповідав сину твоєму і сину сина твого про те, що Я зробив у Єгипті, і про знамення Мої, які Я показав у ньому, і щоб ви знали, що Я Господь.","Мойсей і Аарон прийшли до фараона і сказали йому: так говорить Господь, Бог євреїв: чи довго ти не смиришся переді Мною? відпусти народ Мій, щоб він звершив Мені служіння;","а якщо ти не відпустиш народу Мого, то ось, завтра [у цей самий час] Я наведу сарану на [всю] твою область:","вона покриє лице землі так, що не можна буде бачити землі, і поїсть у вас [усе], що залишилося [на землі], що уціліло від граду; об’їсть також усі дерева, що ростуть у вас на полі,","і наповнить доми твої, доми всіх рабів твоїх і [усі] доми всіх єгиптян, чого не бачили батьки твої, ні батьки батьків твоїх з дня, як живуть на землі, навіть до цього дня. [Мойсей] обернувся і вийшов від фараона.","Тоді раби фараонові сказали йому: чи довго він буде мучити нас? відпусти цих людей, нехай вони звершать служіння Господу, Богу своєму; невже ти ще не бачиш, що Єгипет гине?","І повернули Мойсея й Аарона до фараона, і [фараон] сказав їм: підіть, звершіть служіння Господу, Богу вашому; хто ж і хто піде?","І сказав Мойсей: підемо з малолітніми нашими і старими нашими, з синами нашими і дочками нашими, і з вівцями нашими і з волами нашими підемо, тому що у нас свято Господу [Богу нашому].","[Фараон] сказав їм: нехай буде так, Господь з вами! я готовий відпустити вас: але навіщо з дітьми? бачите, у вас недобрий намір!","ні: підіть одні чоловіки і звершіть служіння Господу, тому що ви цього просили. І вигнали їх від фараона.","Тоді Господь сказав Мойсеєві: простягни руку твою на землю Єгипетську, і нехай нападе сарана на землю Єгипетську і поїсть усю траву земну [і всі плоди дерев], усе, що вціліло від граду.","І простяг Мойсей жезл свій на землю Єгипетську, і Господь навів на цю землю східний вітер, який продовжувався весь той день і всю ніч. Настав ранок, і східний вітер наніс сарану.","І напала сарана на всю землю Єгипетську і лягла по всій країні Єгипетській у великій кількості: раніше не бувало такої сарани, і після цього не буде такої;","вона покрила лице всієї землі, так що землі не було видно, і поїла всю траву земну і всі плоди дерев, що вціліли від граду, і не залишилося ніякої зелені ні на деревах, ні на траві польовій по всій землі Єгипетській.","Фараон поспіхом прикликав Мойсея й Аарона і сказав: згрішив я перед Господом, Богом вашим, і перед вами;","тепер простіть гріх мій ще раз і помоліться Господу Богу вашому, щоб Він тільки відвернув від мене цю смерть.","[Мойсей] вийшов від фараона і помолився Господу.","І підняв Господь із протилежного боку західний дуже сильний вітер, і він поніс сарану і кинув її в Червоне море: не залишилося жодної сарани у всій країні Єгипетській.","Але Господь озлобив серце фараона, і він не відпустив синів Ізраїлевих.","І сказав Господь Мойсеєві: простягни руку твою до неба, і буде темрява на землі Єгипетській, відчутна пітьма.","Мойсей простяг руку свою до неба, і була густа темрява по всій землі Єгипетській три дні;","не бачили одне одного, і ніхто не вставав з місця свого три дні; у всіх же синів Ізраїлевих було світло в житлах їхніх.","Фараон покликав Мойсея [й Аарона] і сказав: підіть, звершіть служіння Господу [Богу вашому], нехай тільки залишиться дрібна і велика худоба ваша, а діти ваші нехай ідуть з вами.","Але Мойсей сказав: [ні,] дай також у руки наші жертви і всепалення, щоб принести Господу Богу нашому;","нехай підуть і стада наші з нами, не залишиться ні копита; тому що з них ми візьмемо на жертву Господу, Богу нашому; але доки не прийдемо туди, ми не знаємо, що принести в жертву Господу [Богу нашому].","І озлобив Господь серце фараона, і він не захотів відпустити їх.","І сказав йому фараон: вийди від мене; бережися, не з’являйся більше перед лицем моїм; у той день, коли ти побачиш лице моє, помреш.","І сказав Мойсей: як сказав ти, так і буде; я не побачу більше лиця твого."],"x":{"2":"1.12.26","3":"1.9.1","4":"25.104.34","12":"1.9.32","13":"1.14.21|3.11.31","14":"25.77.46","15":"25.104.35","16":"1.8.25|1.9.27","19":"1.8.31","20":"1.11.10","21":"31.50.3","22":"25.104.28","23":"29.17.5|29.18.1","24":"1.8.8"}},{"v":["І сказав Господь Мойсеєві: ще одну кару Я наведу на фараона і на єгиптян; після того він відпустить вас звідси; коли ж він буде відпускати [вас], з поспіхом буде гнати вас звідси;","підкажи народу [таємно], щоб кожен у ближнього свого і кожна жінка у ближньої своєї випросили речей срібних і речей золотих [і одягу].","І дав Господь милість народу [Своєму] в очах єгиптян, [і вони давали йому;] та й Мойсей був дуже великим у землі Єгипетській, в очах [фараона і] рабів фараонових і в очах [усього] народу.","І сказав Мойсей: так говорить Господь: опівночі Я пройду посеред Єгипту,","і помре всякий первісток у землі Єгипетській від первістка фараона, який сидить на престолі своїм, до первістка рабині, яка при жорнах, і все первородне з худоби;","і буде крик великий по всій землі Єгипетській, якого не бувало і якого не буде більше;","у всіх же синів Ізраїлевих ні на людину, ні на худобу не ворухне пес язиком своїм, щоб ви знали, яку різницю робить Господь між єгиптянами і між ізраїльтянами.","І прийдуть усі раби твої ці до мене і поклоняться мені, кажучи: вийди ти і весь народ [твій], на чолі якого ти стоїш. Після цього я і вийду. І вийшов [Мойсей] від фараона з гнівом.","І сказав Господь Мойсеєві: не послухав вас фараон, щоб примножилися [знамення Мої і] чудеса Мої в землі Єгипетській.","Мойсей і Аарон зробили всі ці [знамення і] чудеса перед фараоном; але Господь озлобив серце фараона, і він не відпустив синів Ізраїлевих із землі своєї."],"x":{"1":"1.6.1|1.12.33|25.104.38","3":"1.3.21|1.12.36|30.45.1","5":"25.77.51|25.104.36|29.18.5","10":"1.9.16|1.10.20|62.9.17"}},{"v":["І сказав Господь Мойсеєві та Аарону в землі Єгипетській. промовляючи:","місяць цей нехай буде у вас початком місяців, нехай буде він у вас першим між місяцями року.","Скажіть усій громаді [синів] Ізраїлевих так: у десятий день цього місяця нехай кожен візьме одне ягня по родинах, по агнцю на родину;","коли ж родина настільки мала, що не з’їсть ціле ягня, то нехай візьме з сусідом своїм найближчим до свого дому, за кількістю душ, щоб було достатньо для спожиття всього ягняти.","Агнець у вас має бути без вад, чоловічої статі, одноліток; візьміть його від овець або від кіз,","і нехай він зберігається у вас до чотирнадцятого дня цього місяця: тоді нехай заколе його все зібрання громади ізраїльської ввечері","і нехай візьмуть від крови його і помастять на обох одвірках і на поперечині дверей у домах, де будуть їсти його;","нехай з’їдять м’ясо його тієї ж ночі, спечене на вогні; з прісним хлібом і з гіркими травами нехай з’їдять його;","не їжте недопеченого м’яса, або звареного у воді, але їжте спечене на вогні з головою, ногами й нутрощами;","не залишайте від нього до ранку [і кістки його не розтрощуйте], але те, що залишиться від нього до ранку, спаліть на вогні.","Їжте ж його так: стегна ваші нехай будуть підперезані, взуття ваше — на ногах ваших і посохи ваші — в руках ваших, їжте його поспішаючи: це — Пасха Господня.","А Я в цю саму ніч пройду по землі Єгипетській і вражу кожного первістка в землі Єгипетській, від людини до худоби, і над усіма богами єгипетськими вчиню суд. Я Господь.","І буде у вас кров знаменням на домах, де ви перебуваєте, і побачу кров і пройду мимо вас, і не буде у вас пошести згубної, коли буду нищити землю Єгипетську.","І нехай буде вам день цей пам’ятним, і святкуйте в ньому і свято Господнє в [усі] роди ваші; як установлення вічне святкуйте його.","Сім днів їжте прісний хліб; з самого першого дня знищіть квасне в домах ваших, тому що хто буде їсти квасне з першого дня до сьомого дня, душа та знищена буде із середовища Ізраїля.","І в перший день нехай буде у вас священне зібрання, і в сьомий день священне зібрання: ніякої роботи не можна робити в них; тільки те́ , що є кожному, одне те́ можна робити вам.","Дотримуйтесь опрісноків, тому що в цей самий день Я вивів ополчення ваші із землі Єгипетської, і додержуйте день цей у роди ваші, як установлення вічне.","З чотирнадцятого дня першого місяця, з вечора їжте прісний хліб до вечора двадцять першого дня того самого місяця;","сім днів не повинно бути закваски в домах ваших, бо хто буде їсти квасне, душа та знищена буде із громади [синів] Ізраїлевих, чи то подорожній, чи хто природний житель землі тієї.","Нічого квасного не їжте; в усякому місці перебування вашого їжте прісний хліб.","І скликав Мойсей усіх старійшин [синів] Ізраїлевих і сказав їм: виберіть і візьміть собі агнців за сімействами вашими і заколіть пасху;","і візьміть пучок ісопу, і обмочіть у кров, що у посудині, і помажте поперечини й обидва одвірки дверей кров’ю, що у посудині; а ви ніхто не виходьте за двері дому свого до ранку.","І піде Господь, щоб уразити Єгипет, і побачить кров на поперечинах і на обох одвірках, і пройде Господь мимо дверей, і не попустить згубникові ввійти в доми ваші для ураження.","Зберігайте це, як закон для себе і для синів своїх повіки.","Коли ввійдете в землю, яку Господь дасть вам, як Він говорив, дотримуйтеся цього служіння.","І коли скажуть вам діти ваші: що це за служіння?","скажіть [їм]: це пасхальна жертва Господу, Який пройшов мимо домів синів Ізраїлевих в Єгипті, коли уражав єгиптян, і доми наші визволив. І схилився народ і поклонився.","І пішли сини Ізраїлеві і зробили: як повелів Господь Мойсеєві й Аарону, так і зробили.","Опівночі Господь уразив усіх первістків у землі Єгипетській, від первістка фараона, який сидів на престолі своєму, до первістка в’язня, що знаходився у в’язниці, і все первородне з худоби.","І встали вночі фараон сам і всі раби його і весь Єгипет; і зчинився великий крик [по всій землі] Єгипетській, тому що не було дому, де не було б мертвих.","І покликав [фараон] Мойсея та Аарона вночі і сказав [їм]: встаньте, вийдіть із середовища народу мого, як ви, так і сини Ізраїлеві, і підіть, звершуйте служіння Господу [Богу вашому], як говорили ви;","і дрібну і велику худобу вашу візьміть, як ви говорили; і підіть і благословіть мене.","І примушували єгиптяни народ, щоб скоріше вислати його з землі тієї; бо говорили вони: ми усі помремо.","І поніс народ тісто своє, раніше ніж воно вкисло; діжки їх, зав’язані в одежах їхніх, були на плечах їхніх.","І зробили сини Ізраїлеві за словом Мойсея і просили у єгиптян речей срібних і речей золотих і одягу.","Господь же дав милість народу [Своєму] в очах єгиптян: і вони давали йому, і обібрав він єгиптян.","І вирушили сини Ізраїлеві з Раамсеса в Сокхоф — до шестисот тисяч піших чоловіків, крім дітей;","і безліч різноплемінних людей вийшли з ними, і дрібна і велика худоба, стадо дуже велике.","І спекли вони із тіста, що винесли з Єгипту, прісні коржі, тому що воно ще не вкисло, тому що вони були вигнані з Єгипту і не могли баритися, і навіть їжі не приготували собі на дорогу.","Часу ж, у який сини Ізраїлеві [і батьки їхні] жили в Єгипті [і в землі Ханаанській], було чотириста тридцять років.","Після того, як минуло чотириста тридцять років, у цей самий день вийшло все ополчення Господнє з землі Єгипетської вночі.","Це — ніч служіння Господу за визволення їх із землі Єгипетської; ця сама ніч — служіння Господу у всіх синів Ізраїлевих у роди їхні.","І сказав Господь Мойсеєві й Аарону: ось устав Пасхи: ніякий іноплемінник не повинен їсти її;","а всякий раб, куплений за срібло, коли обріжеш його, може їсти її;","поселенець і найманець не повинен їсти її.","В одному домі належить їсти її, [не залишайте від неї до ранку,] не виносьте м’яса геть з дому і кісток її не розтрощуйте.","Уся громада [синів] Ізраїля повинна звершувати її.","Якщо ж оселиться у тебе подорожній і захоче звершити Пасху Господню, то обріж у нього всіх чоловічої статі, і тоді нехай він приступить до звершення її і буде як природний житель землі; а ніякий необрізаний не повинен їсти її;","один закон нехай буде і для природного жителя і для подорожнього, який оселився між вами.","І зробили всі сини Ізраїлеві: як повелів Господь Мойсеєві й Аарону, так і зробили.","У цей самий день Господь вивів синів Ізраїлевих із землі Єгипетської за ополченнями їх."],"x":{"2":"3.9.1|1.13.4|5.4.19","3":"53.1.29|63.5.7","6":"1.16.12|2.23.5|4.16.6","8":"3.9.11","9":"4.16.7","10":"1.23.18|1.34.25","11":"52.12.35|66.6.14|56.1.13","12":"25.135.10|75.11.28|3.33.4","14":"62.10.4","15":"1.23.15|1.34.18","18":"36.45.21|2.23.5|3.28.16","20":"4.16.4|63.5.8","23":"75.11.28","26":"1.10.2|1.13.8|4.6.20","27":"63.11.26","29":"25.77.51|25.104.36|25.134.8|25.135.10|29.18.5","35":"1.3.22","36":"1.3.21|25.104.37","37":"3.33.3|5.24.6|25.135.11-12","40":"0.15.13","43":"1.7.8|64.6.16|66.2.12","45":"65.4.7","46":"3.9.12|53.19.36","48":"63.11.28","49":"2.24.22|65.3.28"}},{"v":["І сказав Господь Мойсеєві, кажучи:","освяти Мені кожного первістка, який розкриває всяке лоно між синами Ізраїлевими, від людини до худоби, [тому що] Мої вони.","І сказав Мойсей народу: пам’ятайте цей день, в який вийшли ви з Єгипту, з дому рабства, бо рукою міцною вивів вас Господь звідти, і не їжте квасного:","сьогодні виходите ви, у місяці Авиві*.","І коли введе тебе Господь [Бог твій] у землю хананеїв і хеттеїв, і аморреїв, і евеїв, і ієвусеїв, [гергесеїв, і ферезеїв,] про яку клявся Він батькам твоїм, що дасть тобі землю, де тече молоко і мед, то звершуй це служіння в цьому місяці;","сім днів їж прісний хліб, і в сьомий день — свято Господу;","прісний хліб потрібно їсти сім днів, і не повинно знаходитися у тебе квасного хліба, і не повинно знаходитися у тебе квасного у всіх межах твоїх.","І оголоси в день той сину твоєму, говорячи: це заради того, що Господь [Бог] зробив зі мною, коли я вийшов з Єгипту.","І нехай буде тобі це знаком на руці твоїй і пам’ятником перед очима твоїми, щоб закон Господній був у вустах твоїх, бо рукою міцною вивів тебе Господь [Бог] із Єгипту.","Виконуй же устав цей у призначений час, з року в рік.","І коли введе тебе Господь [Бог твій] у землю Ханаанську, як Він клявся тобі і батькам твоїм, і дасть її тобі, —","відокремлюй Господу все [чоловічої статі], що розкриває утробу; і все первородне з худоби, яка у тебе буде, чоловічої статі, [присвячуй] Господу,","а всякого з ослів, що розкриває [утробу], заміняй агнцем; а якщо не заміниш, викупи його; і кожного первістка людського із синів твоїх викуповуй.","І коли опісля запитає тебе син твій, говорячи: що це? то скажи йому: рукою міцною вивів нас Господь із Єгипту, із дому рабства;","бо коли фараон опирався відпустити нас, Господь умертвив усіх первістків у землі Єгипетській, від первістка людського до первістка із худоби, — тому я приношу в жертву Господу все, що розкриває утробу, чоловічої статі, а всякого первістка із синів моїх викуповую;","і нехай буде це знаком на руці твоїй і замість пов’язки над очима твоїми, тому що рукою міцною Господь вивів нас з Єгипту.","Коли ж фараон відпустив народ, Бог не повів його по дорозі землі Филистимської, тому що вона близька; бо сказав Бог: щоб не розкаявся народ, побачивши війну, і не повернувся до Єгипту.","І обвів Бог народ дорогою пустельною до Червоного моря. І вийшли сини Ізраїлеві озброєні із землі Єгипетської.","І взяв Мойсей із собою кості Йосифа, бо [Йосиф] клятвою закляв синів Ізраїлевих, сказавши: відвідає вас Бог, і ви із собою винесіть кості мої звідси.","І рушили [сини Ізраїлеві] із Сокхофа і розташувалися станом в Ефамі, у кінці пустелі.","Господь же йшов перед ними вдень у стовпі хмарному, показуючи їм шлях, а вночі у стовпі вогненному, світячи їм, щоб іти їм і вдень і вночі.","Не відлучався стовп хмарний удень і стовп вогненний уночі від лиця [усього] народу."],"x":{"2":"1.22.29|1.34.19|2.27.26|3.3.13|3.8.17|52.2.23","3":"1.23.15","5":"0.15.7|0.15.18-21|0.17.8","7":"63.5.8","8":"1.12.26","9":"4.6.8|4.11.18","10":"1.12.14","11":"0.15.18","12":"1.13.2","13":"1.34.20|3.3.46","14":"1.12.26","15":"1.4.23|1.12.29","16":"4.6.8","17":"63.10.13","18":"25.77.52-53","19":"0.50.25|5.24.32","20":"3.33.6","21":"1.14.19|3.14.14|4.1.33|4.4.37|25.77.14|25.104.39|17.9.19"},"n":{"4":["У місяці колосся."]}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим, щоб вони повернули і розташувалися станом перед Пи-Гахирофом, між Мигдолом і між морем, перед Ваал-Цефоном; навпроти нього поставте стан біля моря.","І скаже фараон [народу своєму] про синів Ізраїлевих: вони заблукали в землі цій, замкнула їх пустеля.","А Я озлоблю серце фараона, і він поженеться за ними, і покажу славу Мою на фараоні і на всьому війську його; і пізнають [усі] єгиптяни, що Я Господь. І зробили так.","І сповіщено було цареві Єгипетському, що народ утік; і навернулося серце фараона і рабів його проти народу цього, і вони сказали: що це ми зробили? навіщо відпустили ізраїльтян, щоб вони не працювали на нас?","[Фараон] запряг колісницю свою і народ свій узяв із собою;","і взяв шістсот колісниць добірних і всі колісниці єгипетські, і начальників над усіма ними.","І озлобив Господь серце фараона, царя Єгипетського [і рабів його], і він погнався за синами Ізраїлевими; сини ж Ізраїлеві йшли під рукою високою.","І погналися за ними єгиптяни, і всі коні з колісницями фараона, і вершники, і все військо його, і наздогнали їх, розташованих біля моря, при Пи-Гахирофі перед Ваал-Цефоном.","Фараон наблизився, і сини Ізраїлеві оглянулись, і ось, єгиптяни йдуть за ними: і дуже злякалися і заволали сини Ізраїлеві до Господа,","і сказали Мойсеєві: хіба немає гробів у Єгипті, що ти привів нас помирати у пустелі? що це ти зробив з нами, вивівши нас з Єгипту?","Чи не це саме говорили ми тобі в Єгипті, сказавши: залиш нас, нехай ми будемо працювати на єгиптян? Тому що краще бути нам у рабстві в єгиптян, ніж померти в пустелі.","Але Мойсей сказав народу: не бійтеся, стійте — і побачите спасіння Господнє, яке Він сотворить вам нині, бо єгиптян, яких бачите ви нині, більше не побачите повік;","Господь буде поборювати за вас, а ви будьте спокійні.","І сказав Господь Мойсеєві: чого ти волаєш до Мене? скажи синам Ізраїлевим, щоб вони йшли,","а ти підніми жезл твій і простягни руку твою на море, і розділи його, і пройдуть сини Ізраїлеві посеред моря по суші;","Я ж озлоблю серце [фараона і всіх] єгиптян, і вони підуть слідом за ними; і покажу славу Мою на фараоні і на всьому війську його, на колісницях його і на вершниках його;","і пізнають [усі] єгиптяни, що я Господь, коли покажу славу Мою на фараоні, на колісницях його і на вершниках його.","І рушив ангел Божий, який ішов перед станом [синів] Ізраїлевих, і пішов позаду них; рушив і стовп хмарний від лиця їх і став за ними;","і ввійшов у середину між станом єгипетським і між станом [синів] Ізраїлевих, і був хмарою і мороком для одних і освітлював ніч для інших, і не зблизилися одні з одними всю ніч.","І простяг Мойсей руку свою на море, і гнав Господь море сильним східним вітром усю ніч і зробив море сушею, і розступилися води.","І пішли сини Ізраїлеві серед моря по суші: во́ди ж були їм стіною з правого і з лівого боків.","Погналися єгиптяни, й увійшли за ними у середину моря всі коні фараона, колісниці його і вершники його.","І в ранкову сторожу поглянув Господь на стан єгиптян зі стовпа вогненного і хмарного і привів у замішання стан єгиптян;","і відібрав колеса у колісниць їхніх, так що вони насилу волокли їх. І сказали єгиптяни: побіжимо від ізраїльтян, тому що Господь поборює за них проти єгиптян.","І сказав Господь Мойсеєві: простягни руку твою на море, і нехай повернуться во́ди на єгиптян, на колісниці їхні і на вершників їхніх.","І простягнув Мойсей руку свою на море, і до ранку вода повернулася у своє місце; а єгиптяни бігли назустріч [воді]. Так потопив Господь єгиптян посеред моря.","І вода повернулася і покрила колісниці і вершників усього війська фараонового, що ввійшли за ними в море; не залишилося жодного з них.","А сини Ізраїлеві пройшли по суші серед моря; води [були] їм стіною з правого і [стіною] з лівого боків.","І визволив Господь у день той ізраїльтян з рук єгиптян, і побачили [сини] Ізраїлеві єгиптян мертвими на березі моря.","І побачили ізраїльтяни руку велику, яку явив Господь над єгиптянами, й убоявся народ Господа і повірив Господу і Мойсеєві, рабові Його. Тоді Мойсей і сини Ізраїлеві заспівали Господу пісню цю і говорили:"],"x":{"2":"3.33.7|32.44.1","4":"1.4.21|1.10.20|36.28.22|62.9.17","8":"29.19.3|1.13.3","9":"5.24.6|21.4.9","11":"25.105.7","13":"13.20.17","14":"4.1.30|4.3.22|6.5.20","15":"5.24.7","19":"1.13.21","21":"25.77.13|25.105.9|25.113.3|5.4.23","22":"63.10.1|75.11.29|19.5.13","24":"25.77.14","25":"4.3.22","27":"29.18.5|29.19.5|1.15.7","28":"25.105.11|25.135.15","31":"25.105.12|25.108.27|13.20.20"}},{"v":["Співаю Господу, бо Він високо звеличився; коня і вершника його ввергнув у море.","Господь кріпость моя і слава моя, Він був мені спасінням. Він Бог мій, і прославлю Його; Бог отця мого, і прославлю Його.","Господь муж брані, Єгова ім’я Йому.","Колісниці фараона і військо його ввергнув Він у море, і вибрані воєначальники його потонули в Червоному морі.","Безодні покрили їх: вони пішли у глибину, як камінь.","Правиця Твоя, Господи, прославилася силою; правиця Твоя, Господи, убила ворога.","Величчю слави Твоєї Ти скинув тих, що повстали проти Тебе. Ти послав гнів Твій, і він попалив їх, як солому.","Від подуву Твого розступилися води, волога стала, як стіна, загустіли безодні в серці моря.","Ворог сказав: поженуся, наздожену, розділю здобич; насититься ними душа моя, оголю меч мій, знищить їх рука моя.","Ти подув духом Твоїм, і покрило їх море: вони занурилися, як свинець, у великих водах.","Хто, як Ти, Господи, між богами? Хто, як Ти, величний святістю, славний похвалами, Творець чудес?","Ти простяг правицю Твою: поглинула їх земля.","Ти ведеш милістю Твоєю народ цей, який Ти визволив, — супроводжуєш силою Твоєю в оселю святині Твоєї.","Почули народи і тремтять: жах огорнув жителів филистимських;","тоді засмутилися князі Едомові, тремтіння огорнуло вождів моавитських, засумували всі жителі Ханаана.","Нехай нападуть на них страх і жах; від величі сили Твоєї нехай оніміють вони, як камінь, поки проходить народ Твій, Господи, поки проходить цей народ, який Ти придбав.","Введи його і насади його на горі насліддя Твого, на місці, яке Ти вчинив оселею Собі, Господи, у святилище, яке створили руки Твої, Владико!","Господь буде царювати повіки й у вічність.","Коли ввійшли коні фараона з колісницями його і з вершниками його в море, то Господь повернув на них води морські, а сини Ізраїлеві пройшли по суші серед моря.","І взяла Маріам пророчиця, сестра Ааронова, у руку свою тимпан, і вийшли за нею всі жінки з тимпанами і радістю.","І заспівала Маріам перед ними: співайте Господу, тому що високо звеличився Він, коня і вершника його ввергнув у море.","І повів Мойсей ізраїльтян від Червоного моря, і вони вступили в пустелю Сур; і йшли вони три дні по пустелі і не знаходили води.","Прийшли в Мерру — і не могли пити води з Мерри, тому що вона була гіркою, чому і наречено тому [місцю] ім’я: Мерра*.","І ремствував народ на Мойсея, говорячи: що нам пити?","[Мойсей] заволав до Господа, і Господь показав йому дерево, і він кинув його у воду, і вода зробилася солодкою. Там Бог дав народу устав і закон і там випробовував його.","І сказав: якщо ти будеш слухатися гласу Господа, Бога твого, і чинитимеш угодне перед очима Його, і слухатимеш заповіді Його, і виконуватимеш усі устави його, то не наведу на тебе жодної з хвороб, які навів Я на Єгипет, тому що Я Господь [Бог твій], цілитель твій.","І прийшли в Єлим; там було дванадцять джерел води і сімдесят фінікових дерев, і розташувалися там станом біля вод."],"x":{"1":"25.105.12","2":"25.117.6-7|31.12.2","3":"6.20.35|1.3.14|38.12.5","5":"17.9.11|76.18.21","6":"25.117.15","7":"1.14.27|31.5.24|31.47.14","8":"31.63.12-13","9":"1.14.3:9","10":"25.73.13","11":"1.18.11|8.2.2|25.39.6","13":"25.76.21","14":"5.2.9","16":"4.4.37","17":"25.43.2-3|25.79.9","18":"25.88.19","19":"1.14.22","20":"25.67.26","22":"0.16.7|3.33.8","25":"30.38.5","26":"1.23.25|4.7.15|31.3.7","27":"3.33.9"},"n":{"23":["Гіркота."]}},{"v":["І рушили з Єлима, і прийшла вся громада синів Ізраїлевих у пустелю Син, що між Єлимом і між Синаєм, у п’ятнадцятий день другого місяця після виходу їх із землі Єгипетської.","І стала ремствувати вся громада синів Ізраїлевих на Мойсея й Аарона в пустелі,","і сказали їм сини Ізраїлеві: о, якби ми померли від руки Господньої у землі Єгипетській, коли ми сиділи біля казанів з м’ясом, коли ми їли хліб досита! бо вивели ви нас у цю пустелю, щоб усе це зібрання виморити голодом.","І сказав Господь Мойсеєві: ось, Я дощем дам вам хліб з неба, і нехай народ виходить і збирає щодня, скільки потрібно на день, щоб Мені випробувати його, чи буде він чинити за законом Моїм, чи ні;","а в шостий день нехай заготовляють, що принесуть, і буде вдвічі проти того, скільки збирають в інші дні.","І сказали Мойсей і Аарон усій [громаді] синів Ізраїлевих: увечері дізнаєтеся ви, що Господь вивів вас із землі Єгипетської,","і вранці побачите славу Господню, бо почув Він ремство ваше на Господа: а ми що́ таке, що нарікаєте на нас?","І сказав Мойсей: дізнаєтеся, коли Господь увечері дасть вам м’яса в їжу, а вранці хліба досита, тому що Господь почув ремство ваше, яке ви підняли проти Нього: а ми що? не на нас ремство ваше, але на Господа.","І сказав Мойсей Аарону: скажи всій громаді синів Ізраїлевих: станьте перед лицем Господа, бо Він почув ремство ваше.","І коли говорив Аарон до всієї громади синів Ізраїлевих, то вони оглянулися до пустелі, і ось, слава Господня явилася в хмарі.","І сказав Господь Мойсеєві, кажучи:","Я почув ремство синів Ізраїлевих; скажи їм: увечері будете їсти м’ясо, а вранці насититеся хлібом — і дізнаєтеся, що Я Господь, Бог ваш.","Увечері налетіли перепели і покрили стан, а вранці лежала роса навколо стану;","роса піднялася, і ось, на поверхні пустелі щось дрібне, круповидне, дрібне, як іній на землі.","І побачили сини Ізраїлеві і говорили одне одному: що це? Бо не знали, що це. І Мойсей сказав їм: це хліб, який Господь дав вам у їжу;","ось що повелів Господь: збирайте його кожен стільки, скільки може з’їсти; по гомору на людину, за числом душ, скільки в кого в наметі, збирайте.","І зробили так сини Ізраїлеві і зібрали, хто багато, хто мало;","і міряли гомором, і в того, хто зібрав багато, не було зайвого, і в того, хто мало, не було нестачі: кожен зібрав, скільки йому з’їсти.","І сказав їм Мойсей: ніхто не залишай цього до ранку.","Але не послухали вони Мойсея, і залишили від цього деякі до ранку, — і завелася черва, і воно засмерділо. І розгнівався на них Мойсей.","І збирали його рано-вранці, кожен скільки йому з’їсти; коли ж обігрівало сонце, воно тануло.","У шостий же день зібрали хліба вдвічі, по два гомори на кожного. І прийшли всі начальники громади і донесли Мойсеєві.","І [Мойсей] сказав їм: ось що сказав Господь: завтра спокій, свята субота Господня; що потрібно пекти, печіть, і що потрібно варити, варіть сьогодні, а що залишиться, відкладіть і збережіть до ранку.","І відклали те до ранку, як повелів [їм] Мойсей, і воно не засмерділо, і черви не було в ньому.","І сказав Мойсей: їжте його сьогодні, бо сьогодні субота Господня; сьогодні не знайдете його на полі;","шість днів збирайте його, а в сьомий день — субота: не буде його в цей день.","Але деякі з народу вийшли в сьомий день збирати — і не знайшли.","І сказав Господь Мойсеєві: чи довго ви будете ухилятися від дотримання заповідей Моїх і законів Моїх?","дивіться, Господь дав вам суботу, тому Він і дає в шостий день хліба на два дні: залишайтеся кожен у себе [у домі своєму], ніхто не виходь від місця свого в сьомий день.","І спочивав народ у сьомий день.","І нарік дім Ізраїлів хлібу тому ім’я: манна; вона була, як коріандрове насіння, біла, на смак же як корж із медом.","І сказав Мойсей: ось що повелів Господь: наповніть [манною] гомор для збереження в роди ваші, щоб бачили хліб, яким Я годував вас у пустелі, коли вивів вас із землі Єгипетської.","І сказав Мойсей Аарону: візьми один сосуд [золотий], і поклади в нього повний гомор манни, і постав його перед Господом, для збереження в роди ваші.","І поставив його Аарон перед ковчегом свідоцтва для збереження, як повелів Господь Мойсеєві.","Сини Ізраїлеві їли манну сорок років, поки не прийшли в землю обітовану; манну їли вони, поки не прийшли до меж землі Ханаанської.","А гомор є десята частина ефи."],"x":{"1":"3.33.11|29.11.2|54.7.36|54.13.18","2":"1.15.24|25.105.13|63.10.10","4":"25.77.25|25.104.40|29.16.20","7":"63.10.10|3.16.11","8":"3.11.18","10":"30.45.3","12":"1.12.6|3.11.7","13":"29.16.2|3.11.31|25.77.27|25.104.40","14":"3.11.7","15":"25.77.24|29.16.20|53.6.31|63.10.3","18":"64.8.15","23":"0.2.2","26":"3.11.6","29":"0.2.2-3","31":"3.11.7|29.16.20","33":"75.9.4","35":"5.5.12|17.9.15"}},{"v":["І рушила вся громада синів Ізраїлевих з пустелі Син у дорогу свою, за повелінням Господнім, і розташувалися станом у Рефидимі, і не було води пити народу.","І дорікав народ Мойсею, і говорив: дайте нам води пити. І сказав їм Мойсей: чого ви дорікаєте мені? чому спокушаєте Господа?","І жадав там народ води, і ремствував народ на Мойсея, говорячи: для чого ти вивів нас з Єгипту, уморити спрагою нас і дітей наших і отари наші?","Мойсей воззвав до Господа і сказав: що мені робити з народом цим? ще трохи, і поб’ють мене камінням.","І сказав Господь Мойсеєві: пройди перед народом, і візьми з собою декого зі старійшин ізраїльських, і жезл твій, яким ти ударив по воді, візьми в руку твою, і піди;","ось, Я стану перед тобою там на скелі в Хориві, і ти удариш у скелю, і піде з неї вода, і буде пити народ. І зробив так Мойсей на очах старійшин ізраїльських.","І нарік місцю тому ім’я: Масса і Мерива*, через докори синів Ізраїлевих і тому, що вони спокушали Господа, говорячи: чи є Господь серед нас, чи ні?","І прийшли амаликитяни і воювали з ізраїльтянами в Рефидимі.","Мойсей сказав Ісусові: вибери нам мужів [сильних] і піди, воюй з амаликитянами; завтра я стану на верхівці пагорба, і жезл Божий буде у руці моїй.","І зробив Ісус, як сказав йому Мойсей, і [пішов] воювати з амаликитянами; а Мойсей і Аарон і Ор зійшли на вершину пагорба.","І коли Мойсей поднімав руки свої, перемагав Ізраїль, а коли опускав руки свої, перемагав Амалик;","але руки Мойсеєві обважніли, і тоді взяли камінь і підклали під нього, і він сів на ньому, Аарон же й Ор підтримували руки його, один з одного, а інший з другого боку. І були руки його піднятими до заходу сонця.","І знищив Ісус Амалика і народ його вістрям меча.","І сказав Господь Мойсею: напиши це для пам’яті в книгу і донеси до Ісуса, що Я повністю зітру пам’ять амаликитян з піднебесної.","І влаштував Мойсей жертовник [Господу] і нарік йому ім’я: Ієгова Ниссі*.","Бо, сказав він, рука на престолі Господа: війна у Господа проти Амалика з роду в рід."],"x":{"1":"3.33.14","2":"3.20.2-3|4.9.7","3":"1.14.11","4":"3.14.10","5":"1.7.20","6":"3.20.11|25.77.16|25.104.41|29.11.4|63.10.4","8":"4.25.17|29.11.3","9":"5.1.1","10":"1.24.14|1.31.2","11":"5.8.18","13":"6.4.23|29.11.3","14":"1.34.27|3.24.20|4.25.17:19"},"n":{"7":["Спокуса й докір."],"15":["Господь прапор мій."]}},{"v":["І почув Іофор, священик мадіамський, тесть Мойсеїв, про все, що зробив Бог для Мойсея і для Ізраїля, народу Свого, коли вивів Господь Ізраїля з Єгипту,","і взяв Іофор, тесть Мойсеїв, Сепфору, дружину Мойсеєву, перед тим повернену,","і двох синів її, з яких одному ім’я Гирсам, тому що говорив Мойсей: я прибулець у землі чужій;","а другому ім’я Єлиєзер, тому що [говорив він] Бог батька мого був мені помічником і врятував мене від меча фараонового.","І прийшов Іофор, тесть Мойсея, з синами його і дружиною його до Мойсея в пустелю, де він розташувався станом біля гори Божої,","і дав знати Мойсею: я, тесть твій Іофор, іду до тебе, і дружина твоя, і два сини її з нею.","Мойсей вийшов назустріч тестю своєму, і поклонився [йому], і цілував його, і після взаємного привітання вони ввійшли в намет.","І розповів Мойсей тестеві своєму про все, що зробив Господь з фараоном і з [усіма] єгиптянами за Ізраїля, і про всі труднощі, які зустріли їх на шляху, і як визволив їх Господь [з руки фараона і з руки єгиптян].","Іофор радів за всі благодіяння, які Господь явив Ізраїлю, коли визволив його з руки єгиптян [і з руки фараона],","і сказав Іофор: благословенний Господь, Який визволив вас з руки єгиптян і з руки фараонової, Який визволив народ цей з-під влади єгиптян;","нині дізнався я, що Господь великий більше за всіх богів, у тому самому, чим вони підносилися над ізраїльтянами.","І приніс Іофор, тесть Мойсеїв, всепалення і жертви Богу; і прийшов Аарон і всі старійшини Ізраїлеві їсти хліб з тестем Мойсеєвим перед Богом.","На другий день сів Мойсей судити народ, і стояв народ перед Мойсеєм з ранку до вечора.","І бачив [Іофор,] тесть Мойсеїв, усе, що він чинить з народом, і сказав: що це таке робиш ти з народом? для чого ти сидиш один, а весь народ стоїть перед тобою з ранку до вечора?","І сказав Мойсей тестеві своєму: народ приходить до мене просити суду у Бога;","коли трапляється в них яка справа, вони приходять до мене, і я суджу між тим та іншим і оголошую [їм] устави Божі і закони Його.","Але тесть Мойсеїв сказав йому: не добре це ти робиш:","ти змучиш і себе і народ цей, який з тобою, тому що занадто важка для тебе ця справа: ти один не можеш виконувати її;","отже, послухай слів моїх; я дам тобі пораду, і буде Бог з тобою: будь ти для народу посередником перед Богом і представляй Богу справи [його];","навчай їх уставів [Божих] і законів [Його], указуй їм шлях [Його], яким вони повинні йти, і діла, які вони повинні робити;","ти ж знайди [собі] з усього народу людей здібних, що бояться Бога, людей правдивих, що ненавидять користь, і постав [їх] над ним тисячоначальниками, стоначальниками, п’ятдесятиначальниками і десятиначальниками [і діловодами];","нехай вони судять народ у всякий час і про всяку важливу справу доносять тобі, а всі малі справи судять самі: і буде тобі легше, і вони понесуть з тобою тягар;","якщо ти зробиш це, і Бог повелить тобі, то ти можеш устояти, і весь народ цей буде відходити у своє місце з миром.","І послухав Мойсей слова тестя свого і зробив усе, що він говорив [йому];","і вибрав Мойсей із усього Ізраїля здібних людей і поставив їх начальниками народу, тисячоначальниками, стоначальниками, п’ятдесятиначальниками і десятиначальниками [і діловодами],","і судили вони народ у всякий час; про [усі] справи важливі доносили Мойсеєві, а всі малі діла судили самі.","І відпустив Мойсей тестя свого, і він пішов у землю свою."],"x":{"1":"1.2.16","2":"1.2.21|1.4.20","3":"1.2.22","4":"1.2.15","5":"1.3.1","6":"3.10.29","11":"1.1.13|1.15.11|12.17.25","12":"4.12.7","18":"4.1.9","21":"3.11.16|4.1.13|13.19.5-6","25":"3.11.16|4.1.15|12.27.1","26":"4.1.17","27":"3.10.30"}},{"v":["У третій місяць після виходу синів Ізраїля з землі Єгипетської, у самий день нового молодого місяця, прийшли вони в пустелю Синайську.","І рушили вони з Рефидима, і прийшли в пустелю Синайську, і розташувалися там станом у пустелі; і розташувався там Ізраїль станом навпроти гори.","Мойсей зійшов до Бога [на гору], і воззвав до нього Господь з гори, говорячи: так скажи дому Якова і звісти синів Ізраїлевих:","ви бачили, що Я зробив єгиптянам, і як Я носив вас [ніби] на орлиних крилах, і приніс вас до Себе;","отже, якщо ви будете слухатися гласу Мого і дотримувати завіт Мій, то будете Моїм уділом з усіх народів, тому що Моя вся земля,","а ви будете у Мене царством священиків і народом святим; ось слова, які ти скажеш синам Ізраїлевим.","І прийшов Мойсей і скликав старійшин народу і переповів їм усі ці слова, що заповів йому Господь.","І весь народ відповідав одностайно, говорячи: усе, що сказав Господь, виконаємо [і будемо слухняні]. І доніс Мойсей слова народу Господу.","І сказав Господь Мойсеєві: ось, Я прийду до тебе в густій хмарі, щоб чув народ, як Я буду говорити з тобою, і повірив тобі назавжди. І Мойсей оголосив слова народу Господу.","І сказав Господь Мойсею: піди до народу, [оголоси] й освяти його сьогодні і завтра; нехай вимиють одяг свій,","щоб бути готовими до третього дня: тому що в третій день зійде Господь перед очима всього народу на гору Синай;","і проведи для народу смугу з усіх боків і скажи: стережіться підніматися на гору і доторкатися до підошви її; всякий, хто доторкнеться до гори, відданий буде на смерть,","рука нехай не доторкнеться до нього, а нехай поб’ють його камінням, або застрелять стрілою; чи то худоба, чи людина, нехай не залишиться в живих; під час протяжного трубного звуку, [коли хмара відійде від гори,] можуть вони піднятися на гору.","І зійшов Мойсей з гори до народу й освятив народ, і вони вимили одяг свій.","І сказав народу: будьте готові до третього дня; не доторкайтеся до дружин.","На третій день, коли настав ранок, були громи і блискавки, і густа хмара над горою [Синайською], і трубний звук дуже сильний; і затремтів увесь народ, що був у стані.","І вивів Мойсей народ зі стану назустріч Богу, і стали біля підошви гори.","Гора ж Синай уся димілася від того, що Господь зійшов на неї у вогні; і піднімався від неї дим, як дим з печі, і вся гора сильно коливалася;","і звук трубний ставав сильнішим і сильнішим. Мойсей говорив, і Бог відповідав йому голосом.","І зійшов Господь на гору Синай, на вершину гори, і прикликав Господь Мойсея на вершину гори, і зійшов Мойсей.","І сказав Господь Мойсеєві: зійди і підтвердь народу, щоб він не поривався до Господа бачити Його, і щоб не впав багато хто з нього;","священики ж, що наближаються до Господа [Бога], повинні освятити себе, щоб не уразив їх Господь.","І сказав Мойсей Господу: не може народ підняться на гору Синай, тому що Ти застеріг нас, сказавши: проведи смугу навколо гори й освяти її.","І Господь сказав йому: піди, зійди, потім піднімись ти і з тобою Аарон; а священики і народ нехай не пориваються сходити до Господа, щоб [Господь] не уразив їх.","І зійшов Мойсей до народу і переповів йому."],"x":{"2":"3.33.15","3":"54.7.38","4":"4.29.2","5":"4.5.2|25.23.1","6":"56.2.9","8":"4.5.27|4.26.17|1.20.18|1.24.16|3.9.15","10":"2.11.45|5.3.5|8.16.5","12":"75.12.20","14":"5.3.5","15":"8.21.4|63.7.5","16":"4.5.4","17":"4.4.10","18":"4.4.11|6.5.4-5|75.12.18","19":"54.7.38","20":"10.19.8","21":"1.33.20|6.6.22|63.10.8","22":"2.10.3"}},{"v":["І промовив Бог [до Мойсея] усі слова ці, говорячи:","Я Господь, Бог твій, Який вивів тебе з землі Єгипетської, з дому рабства;","нехай не буде в тебе інших богів перед лицем Моїм.","Не роби собі кумира і ніякого зображення того, що на небі вгорі, і що на землі внизу, і що у воді нижче землі;","не поклоняйся їм і не служи їм, бо Я Господь, Бог твій, Бог ревнитель, що карає дітей за провину батьків до третього і четвертого роду тих, які ненавидять Мене,","і творить милість до тисячі родів тим, що люблять Мене і дотримуються заповідей Моїх.","Не вимовляй імені Господа, Бога твого, марно, тому що Господь не залишить без покарання того, хто промовляє ім’я Його марно.","Пам’ятай день суботній, щоб святити його;","шість днів працюй і виконуй [у них] усякі справи твої,","а день сьомий — субота Господу, Богу твоєму: не роби в цей день ніякої справи ні ти, ні син твій, ні дочка твоя, ні раб твій, ні рабиня твоя, ні [віл твій, ні осел твій, ні всяка] худоба твоя, ні прибулець, який в оселях твоїх;","бо за шість днів створив Господь небо і землю, море й усе, що в них, а на день сьомий спочив; тому благословив Господь день суботній і освятив його.","Шануй батька твого і матір твою, [щоб тобі було добре і] щоб продовжилися дні твої на землі, яку Господь, Бог твій, дає тобі.","Не вбивай.","Не перелюбствуй.","Не кради.","Не говори неправдивого свідчення на ближнього твого.","Не бажай дому ближнього твого; не бажай дружини ближнього твого, [ні поля його,] ні раба його, ні рабині його, ні вола його, ні осла його, [ні всякої худоби його,] нічого, що у ближнього твого.","Весь народ бачив громи і полум’я і звук трубний, і гору, що диміла, і побачивши те, [весь] народ відступив і став віддалік.","І сказали Мойсею: говори ти з нами, і ми будемо слухати, але щоб не говорив з нами Бог, щоб нам не померти.","І сказав Мойсей народу: не бійтеся; Бог [до вас] прийшов, щоб випробувати вас і щоб страх Його був перед лицем вашим, щоб ви не грішили.","І стояв [весь] народ віддалік, а Мойсей вступив у морок, де Бог.","І сказав Господь Мойсеєві: так скажи [дому Якова і звісти] синам Ізраїлевим: ви бачили, як Я з неба говорив вам;","не робіть переді Мною богів срібних, або богів золотих, не робіть собі:","зроби Мені жертовник із земли і принось на ньому всепалення твої і мирні жертви твої, овець твоїх і волів твоїх; на всякому місці, де Я покладу пам’ять імені Мого, Я прийду до тебе і благословлю тебе;","якщо ж будеш робити Мені жертовник з каменів, то не споруджуй його з обтесаних, бо, як тільки накладеш на них тесало твоє, то оскверниш їх;","і не піднімайся по сходинках до жертовника Мого, щоб не відкрилася при ньому нагота твоя."],"x":{"1":"4.4.13","2":"4.5.6|25.80.11","4":"2.26.1|4.5.8|25.96.7","5":"3.14.18|4.5.9","6":"1.34.7|4.5.10","7":"2.19.12|4.5.11|50.5.33","8":"1.31.13|4.5.12|36.20.12","9":"2.23.3|4.5.13","10":"4.5.14|50.12.2","11":"0.2.2|1.31.17|75.4.4","12":"4.5.16|50.15.4|51.7.10|66.6.2-3|30.3.8","13":"4.5.17|50.5.21|50.19.18|51.10.19|62.13.9","14":"4.5.18|50.5.27","15":"4.5.19","16":"4.5.20","17":"4.5.21|62.7.7|62.13.9","18":"75.12.19","19":"4.18.16|75.12.19-20","20":"0.22.1","21":"10.8.12|75.12.18","23":"1.34.17","24":"1.27.8|4.12.11","25":"4.27.5|5.8.31","26":"1.28.42"}},{"v":["І ось закони, які ти оголосиш їм:","якщо купиш раба єврея, нехай він працює [на тебе] шість років, а на сьомий [рік] нехай вийде на волю задарма;","якщо він прийшов один, нехай один і вийде; а якщо він одружений, нехай вийде з ним і дружина його;","якщо ж господар його дав йому дружину і вона народила йому синів або дочок, то дружина і діти її нехай залишаться у господаря її, а він вийде один;","але якщо раб скаже: люблю господаря мого, дружину мою і дітей моїх, не піду на волю, —","то нехай господар його приведе його перед богами* і поставить його до дверей, або до одвірка, і проколе йому господар його вухо шилом, і він залишиться рабом його повік.","Якщо хто продасть дочку свою в рабині, то вона не може вийти, як виходять раби;","якщо вона не угодна господарю своєму і він не обручить її, нехай дозволить викупити її; а чужому народу продати її [господар] не владний, коли сам зневажив її;","якщо він обручить її з сином своїм, нехай вчинить з нею за правом дочок;","якщо ж іншу візьме за нього, то вона не повинна позбавлятися їжі, одягу і подружнього співжиття;","а якщо він цих трьох речей не зробить для неї, нехай вона відійде задарма, без викупу.","Хто вдарить людину так, що вона помре, нехай буде відданий на смерть;","але якщо хто не злонавмисно, а Бог попустив йому потрапити під руки його, то Я призначу в тебе місце, куди втекти [убивці];","а якщо хто з наміром умертвить ближнього підступно [і прибіжить до жертовника], то і від жертовника Мого бери його на смерть.","Хто вдарить батька свого, або свою матір, того слід віддати на смерть.","Хто украде людину [із синів Ізраїлевих] і [поневоливши її] продасть її, або знайдеться вона в руках у нього, то слід віддати його на смерть.","Хто лихословить на батька свого, або свою матір, того слід віддати на смерть.","Коли сваряться [двоє], і один чоловік вдарить іншого каменем, або кулаком, і той не помре, але зляже в постіль,","то, якщо він устане і буде виходити з дому з допомогою палиці, той, хто вдарив [його] не буде підлягати смерті; тільки нехай заплатить за зупинку в його роботі і дасть на лікування його.","А якщо хто вдарить раба свого, або служницю свою палкою, і вони помруть під рукою його, то він повинен бути покараним;","але якщо вони день або два дні переживуть, то не слід карати його, тому що це його срібло.","Коли б’ються люди, й ударять вагітну жінку, і вона викине, але не буде іншої шкоди, то взяти з винного пеню, яку накладе на нього чоловік тієї жінки, і він повинен заплатити її при посередниках;","а якщо буде пошкодження, то віддай душу за душу,","око за око, зуб за зуб, руку за руку, ногу за ногу,","обпалення за обпалення, рану за рану, удар за удар.","Якщо хто раба свого ударить в око, або служницю свою в око, і пошкодить його, нехай відпустить їх на волю за око;","і якщо виб’є зуб рабу своєму, або рабі своїй, нехай відпустить їх на волю за зуб.","Якщо віл забодає чоловіка або жінку до смерті, то вола побити камінням і м’яса його не їсти; а господар вола не винний;","але якщо віл був битливим і вчора і третього дня, і господар його був сповіщений про це, не стеріг його, а він убив чоловіка або жінку, то вола побити камінням, і господаря його віддати на смерть;","якщо на нього буде накладений викуп, нехай дасть за душу свою викуп, який буде накладений на нього.","Чи забодає сина, чи забодає дочку, — за цим самим законом чинити з ним.","Якщо віл забодає раба або рабу, то господареві їх заплатити тридцять сиклів срібла, а вола побити камінням.","Якщо хто розкриє яму, або якщо викопає яму і не закриє її, і впаде в неї віл або осел,","то господар ями повинен заплатити, віддати срібло господарю їх, а труп буде його.","Якщо чий-небудь віл забодає до смерті вола в сусіда його, нехай продадуть живого вола і розділять навпіл ціну його; також і убитого нехай розділять навпіл;","а якщо відомо було, що віл битливий і вчора і третього дня, але господар його [бувши сповіщений про це] не стеріг його, то він повинний заплатити вола за вола, а убитий буде його."],"x":{"2":"4.15.12|32.34.14","4":"2.25.44|0.21.10|65.4.24","5":"4.15.16","6":"2.25.39-41","9":"1.22.16","12":"2.24.17","13":"4.19.2","14":"4.19.11|10.2.29:31","17":"2.20.9|26.20.20|50.15.4|51.7.10","19":"9.3.29","20":"2.25.39","24":"2.24.20|4.19.21|50.5.38","28":"0.9.5"},"n":{"6":["Тобто перед суддями. Пс. 81, 1, 2, 6."]}},{"v":["Якщо хто украде вола або вівцю і заколе або продасть, то п’ять волів заплатить за вола і чотири вівці за вівцю.","Якщо хто застане злодія, що підкопує, і вдарить його, так що він помре, то кров не ставиться в провину йому;","але якщо зійшло над ним сонце, то ставиться в провину йому кров. Той, хто вкрав, повинен заплатити; а якщо нема чим, то нехай продадуть його для сплати за вкрадене ним;","якщо [він буде спійманий і] вкрадене знайдеться в нього в руках живим, чи то віл, або осел, або вівця, нехай заплатить [за них] удвічі.","Якщо хто потравить поле, або виноградник, пустивши худобу свою травити чуже поле, [дивлячись по плодах його нехай заплатить зі свого поля; а якщо потравить усе поле,] нехай відшкодує кращим з поля свого і кращим з виноградника свого.","Якщо з’явиться вогонь і охопить терен і випалить копиці, або жниво, або поле, то повинен заплатити той, хто вчинив цю пожежу.","Якщо хто віддасть ближньому на збереження срібло або речі, і вони будуть украдені з дому його, то, якщо знайдеться злодій, нехай він заплатить удвічі;","а якщо не знайдеться злодій, нехай господар дому прийде до суддів [і заприсягнеться], що не простягав руки своєї на власність ближнього свого.","Про всяку річ суперечливу, про вола, про осла, про вівцю, про одяг, про всяку річ загублену, про яку хто-небудь скаже, що вона його, справа обох повинна бути доведена до суддів: кого звинуватять судді, той заплатить ближньому своєму вдвічі.","Якщо хто віддасть ближньому своєму осла, або вола, або вівцю, або яку іншу худобу на збереження, а він помре, або буде пошкоджений, або украдений, так що ніхто цього не побачить, —","клятва перед Господом хай буде між обома в тім, що той, хто взяв, не простяг руки своєї на власність ближнього свого; і господар повинний прийняти, а той не буде платити;","а якщо украдено буде у нього, то повинен заплатити господарю його;","якщо ж буде звіром розтерзаний, то нехай на доказ представить роздерте: за розідране він не платить.","Якщо хто позичить у ближнього свого худобу, і вона буде пошкоджена, або помре, а господаря його не було при ній, то повинен заплатити;","якщо ж господар його був при ній, то не повинен платити; якщо вона взята у найми за гроші, то нехай і піде за ту ціну.","Якщо звабить хто дівчину незаручену і переспить з нею, нехай дасть їй віно [і візьме її] собі за дружину;","а якщо батько не погодиться [і не захоче] видати її за нього, нехай заплатить [батькові] стільки срібла, скільки належить на віно дівчатам.","Ворожки не залишай у живих.","Усякий скотоложник нехай буде відданий на смерть.","Той, хто приносить жертву богам, крім одного Господа, нехай буде знищений.","Прибульця не утискуй і не пригноблюй його, тому що ви самі були прибульцями в землі Єгипетській.","Ні вдови, ні сироти не утискуйте;","якщо ж ти утиснеш, то, коли вони будуть волати до Мене, Я почую волання їх,","і запалає гнів Мій, і уб’ю вас мечем, будуть дружини ваші вдовами і діти ваші сиротами.","Якщо даси гроші в борг бідному з народу Мого, то не пригноблюй його і не накладай на нього лихви.","Якщо візьмеш у заставу одежу ближнього твого, то до заходу сонця поверни її,","тому що вона є єдиний покров у нього, вона — одіяння тіла його: в чому буде він спати? отже, коли він буде волати до Мене, Я почую, бо Я милосердий.","Суддів не лихослов і начальника в народі твоєму не паплюж.","Не барися [приносити Мені] початки від току твого і від точила твого; віддавай Мені первістка із синів твоїх;","те саме роби з волом твоїм і з вівцею твоєю [і з ослом твоїм]: сім днів нехай вони будуть біля матері своєї, а у восьмий день віддавай їх Мені.","І будете в Мене людьми святими; і м’яса, роздертого звіром у полі, не їжте, псам кидайте його."],"x":{"1":"9.12.6","8":"1.21.6|25.81.1:6|53.10.35","12":"0.31.39","16":"4.22.28","18":"2.19.31|2.20.27|4.18.11","20":"4.13.13:15","21":"1.23.9|2.19.33-34","22":"48.7.10","25":"2.25.36|25.14.5|36.18.8","26":"4.24.12","28":"54.23.5","29":"36.44.30|1.13.2|52.2.23","31":"2.22.8|36.44.31"}},{"v":["Не прислухайся до пустих чуток, не давай руки твоєї нечестивому, щоб бути свідком неправди.","Не йди за більшістю на зло, і не вирішуй по́зову, відступаючи за більшістю від правди;","і бідному не потурай у по́зові його.","Якщо знайдеш вола ворога твого, або осла його, що заблукав, приведи його до нього;","якщо побачиш осла ворога твого, що впав під ношею своєю, то не залишай його; розв’юч разом з ним.","Не суди перекручено по́зову бідного твого.","Віддаляйся від неправди і не умертвляй невинного і правого, бо Я не виправдаю беззаконника.","Дарів не приймай, бо дари роблять сліпими зрячих і спотворюють справу правих.","Прибульця не кривдь [і не утискуй його]: ви знаєте душу прибульця, тому що самі були прибульцями в землі Єгипетській.","Шість років засівай землю твою і збирай врожай її,","а в сьомий залишай її в спокої, щоб годувались убогі з твого народу, а залишками після них годувалися звірі польові; так само чини з виноградником твоїм і з маслиною твоєю.","Шість днів роби діла твої, а в сьомий день спочивай, щоб відпочив віл твій і осел твій і заспокоївся син раби твоєї і прибулець.","Дотримуйтесь усього, що Я сказав вам, і імен інших богів не згадуйте; нехай не чується воно з уст твоїх.","Тричі на рік святкуй Мені:","дотримуйся свята опрісноків: сім днів їж прісний хліб, як Я повелів тобі, у призначений час місяця Авива, тому що в ньому ти вийшов з Єгипту; і нехай не з’являються перед лице Моє з порожніми руками;","додержуйся і свята жнив перших плодів праці твоєї, які ти сіяв на полі, і свята збирання плодів наприкінці року, коли збереш з поля працю твою.","Тричі на рік повинні з’являтися всі чоловічої статі твої перед лице Владики, Господа [твого].","[Коли вижену язичників від лиця твого і поширю межі твої], не виливай крови жертви Моєї на квасне, і жир від святкової жертви Моєї не повинен залишатися до ранку.","Початки плодів землі твоєї принось у дім Господа, Бога твого. Не вари козеняти в молоці матері його.","Ось, Я посилаю перед тобою ангела [Мого] оберігати тебе на путі і ввести тебе в те місце, яке Я приготував [тобі];","зберігай себе перед лицем Його і слухай гласу Його; не протився Йому, тому що Він не простить гріха вашого, бо ім’я Моє в Ньому.","[Якщо будеш слухати гласу Мого, і будеш виконувати усе, що скажу тобі, і збережеш завіт Мій, то ви будете в Мене народом обраним з усіх племен, бо вся земля Моя; ви будете у Мене царственим священством і народом святим. Ці слова скажи синам Ізраїлевим.] Якщо ти будеш слухати гласу Його і виконувати все, що скажу [тобі], то ворогом буду ворогів твоїх і супротивником противників твоїх.","Коли піде перед тобою ангел Мій і поведе тебе до аморреїв, хеттеїв, ферезеїв, хананеїв, [гергесеїв,] евеїв та ієвусеїв, і знищу їх [від лиця вашого],","то не поклоняйся богам їхнім, і не служи їм, і не наслідуй діл їхніх, але розтрощи їх і зруйнуй стовпи їхні:","служіть Господу, Богу вашому, і Він благословить хліб твій [і вино твоє] і воду твою; і відверну від вас хвороби.","Не буде в тебе тих, що передчасно народжують, і безплідних у землі твоїй; число днів твоїх зроблю повним.","Жах Мій пошлю перед тобою, і в збентеження приведу всякий народ, до якого ти прийдеш, і буду повертати до тебе тил усіх ворогів твоїх;","пошлю перед тобою шершнів, і вони поженуть від лиця твого [аморреїв,] евеїв, [ієвусеїв,] хананеїв і хеттеїв;","не вижену їх від лиця твого в один рік, щоб земля не зробилася порожньою і не розмножилися проти тебе звірі польові:","мало-помалу буду проганяти їх від тебе, поки ти не розмножишся і не візьмеш у володіння землі цієї.","Прокладу межі твої від моря Червоного до моря Филистимського і від пустелі до ріки [великої Євфрату], бо віддам до рук ваших жителів цієї землі, і проженеш їх від лиця твого;","[не змішуйся і] не укладай союзу ні з ними, ні з богами їхніми;","не повинні вони жити в землі твоїй, щоб вони не ввели тебе у гріх проти Мене; бо якщо ти будеш служити богам їхнім, то це буде для тебе сіттю."],"x":{"1":"2.19.11","3":"2.19.15","4":"4.22.1","5":"52.14.5","6":"4.16.19|31.10.1-2","7":"37.13.62","8":"4.16.19|30.20.29","9":"4.10.19|0.46.5|1.22.21","10":"2.25.3","12":"1.20.9|2.23.3","13":"4.27.1|1.20.3|5.23.7","15":"1.13.3|30.35.4","16":"2.23.34","17":"1.34.23|4.16.16","19":"1.34.26|4.14.21","20":"1.13.21|1.14.19","21":"31.63.10|32.23.6|53.10.30","22":"4.18.15|0.12.3","23":"1.33.2|4.7.1|5.24.11","24":"1.20.5|0.35.2","25":"50.6.33|1.15.26","26":"4.7.14","27":"0.35.5","28":"4.7.20|5.24.12","31":"0.15.18|0.28.14|3.34.2","32":"1.34.15|4.7.2","33":"1.34.12"}},{"v":["І Мойсеєві сказав Він: піднімись до Господа ти й Аарон, Надав і Авиуд і сімдесят зі старійшин Ізраїлевих, і поклоніться [Господу] здаля;","Мойсей один нехай наблизиться до Господа, а вони нехай не наближаються, і народ нехай не піднімається з ним.","І прийшов Мойсей і переказав народу всі слова Господні і всі закони. І відповів увесь народ в один голос, і сказали: все, що сказав Господь, зробимо [і будемо слухняні].","І написав Мойсей усі слова Господні і, вставши рано-вранці, поставив під горою жертовник із дванадцяти каменів, за числом дванадцяти колін Ізраїлевих;","і послав юнаків із синів Ізраїлевих, і принесли вони всепалення, і закололи тельців для мирної жертви Господу [Богу].","Мойсей, узявши половину крови, влив у чаші, а другою половиною окропив жертовник;","і взяв книгу завіту і прочитав уголос народу, і сказали вони: все, що сказав Господь, зробимо і будемо слухняні.","І взяв Мойсей крови й окропив народ, говорячи: ось кров завіту, який Господь уклав з вами про всі слова ці.","Потім зійшов Мойсей і Аарон, Надав і Авиуд і сімдесят зі старійшин Ізраїлевих,","і бачили [місце стояння] Бога Ізраїлевого; і під ногами Його щось подібне до роботи з чистого сапфіру і, як саме небо, ясне.","І Він не простяг руки Своєї на обраних з синів Ізраїлевих: вони бачили [місце] Бога, і їли і пили.","І сказав Господь Мойсеєві: зійди до Мене на гору і будь там; і дам тобі скрижалі кам’яні, і закон і заповіді, що Я написав для навчення їх.","І встав Мойсей з Ісусом, слугою своїм, і пішов Мойсей на гору Божу,","а старійшинам сказав: залишайтеся тут, поки ми не повернемося до вас; ось Аарон і Ор з вами; хто буде мати справу, нехай приходить до них.","І зійшов Мойсей на гору, і покрила хмара гору,","і слава Господня осінила гору Синай; і покривала її хмара шість днів, а в сьомий день [Господь] воззвав до Мойсея з середини хмари.","Вигляд же слави Господньої на вершині гори був перед очима синів Ізраїлевих, як вогонь, що поїдає.","Мойсей вступив у середину хмари і зійшов на гору; і був Мойсей на горі сорок днів і сорок ночей."],"x":{"1":"1.18.25","3":"53.7.19","4":"0.31.45","5":"3.3.41","7":"18.5.1","8":"75.9.19-20","10":"1.33.20|36.1.26|36.10.1","11":"1.19.12|1.33.22","14":"1.31.2|1.35.30","16":"1.19.9|10.8.10-11|13.7.1","17":"4.4.24|4.9.3|75.12.29","18":"1.34.28|4.9.9:18"}},{"v":["І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим, щоб вони зробили Мені приношення; від усякої людини, у якої буде ревність, приймайте приношення Мені.","Ось приношення, що ви повинні приймати від них: золото і срібло і мідь,","і вовну блакитну, пурпурову і червлену, і висон, і козячу [вовну],","і шкури баранячі червоні, і шкіри сині, і дере́ва ситим,","єлей для світильника, пахощі для єлею помазання і для запашного кадіння,","камінь онікс і камені вставні для ефода* і для наперсника.","І влаштують вони Мені святилище, і буду перебувати серед них;","усе [зробіть], як Я показую тобі, і зразок скинїї і зразок усіх сосудів її; так і зробіть.","Зробіть ковчег з дерева ситим: довжина йому два лікті з половиною, і ширина йому півтора ліктя, і висота йому півтора ліктя;","і обклади його чистим золотом, зсередини і ззовні покрий його; і зроби нагорі навколо нього золотий вінець [плетений];","і відлий для нього чотири золотих кільця й укріпи на чотирьох нижніх кутах його: два кільця на одному боці його, два кільця на другому боці його.","Зроби з дерева ситим жердини й обклади їх [чистим] золотом;","і вклади жердини в кільця, з боків ковчега, щоб за допомогою них носити ковчег;","у кільцях ковчега повинні бути жердини і не повинні зніматися з нього.","І поклади в ковчег одкровення, що Я дам тобі.","Зроби також кришку з чистого золота: довжина її два лікті з половиною, а ширина її півтора ліктя","і зроби із золота двох херувимів: карбованої роботи, зроби їх на обох кінцях кришки;","зроби одного херувима з одного краю, а другого херувима з іншого краю; такими, що виступають з кришки, зробіть херувимів на обох краях її;","і будуть херувими з розпростертими догори крилами, покриваючи крилами своїми кришку, а лицями своїми будуть один до одного: до кришки будуть лиця херувимів.","І поклади кришку на ковчег згори, у ковчег же поклади одкровення, що Я дам тобі;","там Я буду відкриватися тобі і говорити з тобою над кришкою, посеред двох херувимів, які над ковчегом одкровення, про усе, що буду заповідувати через тебе синам Ізраїлевим.","І зроби стіл з дерева ситим, довжиною у два лікті, шириною в лікоть, і висотою у півтора ліктя,","і обклади його золотом чистим, і зроби навколо нього золотий вінець [плетений];","і зроби навколо нього стінки в долоню і біля стінок його зроби золотий вінець навколо;","і зроби для нього чотири кільця золотих і закріпи кільця на чотирьох кутах біля чотирьох ніжок його;","на стінках повинні бути кільця, щоб вкладати жердини для носіння на них столу;","а жердини зроби з дерева ситим і обклади їх [чистим] золотом, і будуть носити на них цей стіл;","зроби також для нього блюдо, кадильниці, чаші і кружки, щоб возливати ними: із золота чистого зроби їх;","і покладай на стіл хліби предкладення перед лицем Моїм постійно.","І зроби світильник із золота чистого; карбованим повинен бути цей світильник; стебло його, віття його, чашечки його, яблука його і квіти його повинні виходити з нього;","шість гілок повинні виходити з боків його: три гілки світильника з одного боку його і три гілки світильника з іншого боку його;","три чашечки на зразок мигдалевої квітки, з яблуком і квітами, повинні бути на одній гілці, і три чашечки на зразок мигдалевої квітки на іншій гілці, з яблуком і квітами: так на всіх шести гілках, що виходять із світильника;","а на стеблі світильника повинні бути чотири чашечки на зразок мигдалевої квітки з яблуками і квітами;","у шести гілок, що виходять із стебла світильника, яблуко під двома гілками його, і яблуко під іншими двома гілками, і яблуко під третіми двома гілками його [і на світильнику чотири чашечки, на зразок мигдалевої квітки];","яблуко і гілки їх з нього повинні виходити: він весь повинен бути карбований, цільний, з чистого золота.","І зроби до нього сім лампад і постав на нього лампади його, щоб світили на передній бік його;","і щипці до нього і лотки до нього [зроби] з чистого золота;","з таланта золота чистого нехай зроблять його з усіма цими приналежностями.","Дивися, зроби їх за тим зразком, який показано тобі на горі."],"x":{"2":"1.35.5","9":"1.26.30","16":"1.16.34|75.9.4","17":"1.37.6","20":"75.9.5","21":"1.26.34|4.10.2","22":"1.29.42","23":"1.35.13|75.9.2","30":"2.24.6|8.21.6|10.7.48","31":"1.35.14|3.8.4","33":"48.4.2","37":"3.8.2","40":"54.7.44|75.8.5"},"n":{"7":["Верхній короткий одяг."]}},{"v":["Скинію ж зроби з десяти покривал крученого висону і з блакитної, пурпурової і червленої вовни, і херувимів зроби на них мистецькою роботою;","довжина кожного покривала двадцять вісім ліктів, а ширина кожного покривала чотири лікті: міра одна всім покривалам.","П’ять покривал нехай будуть з’єднані одне з одним, і інші п’ять покривал з’єднані одне з одним.","Зроби [до них] петлі блакитного кольору на краю першого покривала, що в кінці з’єднує обидві половини; так зроби і на краю останнього покривала, що з’єднує обидві половини;","п’ятдесят петель зроби на одному покривалі і п’ятдесят петель зроби на краю покривала, що з’єднується з іншим; петлі повинні відповідати одна одній;","і зроби п’ятдесят гачків золотих і гачками з’єднай покривала одне з одним, і буде скинія одним цілим.","І зроби покривала із козячої вовни, щоб покривати скинію; одинадцять покривал зроби таких;","довжина одного покривала тридцять ліктів, а ширина чотири лікті; це одне покривало: одинадцятьом покривалам одна міра.","І з’єднай п’ять покривал окремо і шість покривал окремо; шосте покривало зроби подвійне з переднього боку скинії.","Зроби п’ятдесят петель на краю крайнього покривала, для з’єднання його з другим, і п’ятдесят петель [зроби] на краю іншого покривала, для з’єднання з ним;","зроби п’ятдесят гачків мідних, і вклади гачки в петлі, і з’єднай покров, щоб він складав одне.","А лишок, що залишається від покривал скиній, — половина зайвого покривала нехай буде звішена на задньому боці скинії;","а лишок від довжини покривал скинії, на лікоть з одного і на лікоть з іншого боку, нехай буде звішений з боків скинії з тієї і з другої сторони, для покриття її.","І зроби покриття для покрова зі шкур баранячих червоних і ще покров верхній зі шкур синіх.","І зроби бруси для скинії з дерева ситим, щоб вони стояли:","довжиною в десять ліктів [зроби] брус, і півтора ліктя кожному брусу ширина;","у кожного бруса по два шипи [на кінцях], один навпроти другого: так зроби на усіх брусах скинії.","Так зроби бруси для скинії: двадцять брусів для полуденної сторони до півдня,","і під двадцять брусів зроби сорок срібних підніжок: два підніжки під один брус для двох шипів його, і два підніжки під другий брус для двох шипів його;","і двадцять брусів для другої сторони скинії до півночі,","і для них сорок підніжок срібних: два підніжки [для двох шипів його] під один брус, і два подніжки під другий брус [для двох шипів його];","для заднього ж боку скинії на захід зроби шість брусів","і два бруси зроби для кутів скинії на задній бік;","вони повинні бути з’єднані внизу і з’єднані вгорі до одного кільця: так повинно бути з ними обома; для обох кутів нехай будуть вони;","і таких буде вісім брусів, і для них срібних підніжків шістнадцять: два підніжки під один брус, і два підніжки під другий брус [для двох шипів його].","І зроби жердини з дерева ситим, п’ять [жердин] для брусів одного боку скинії,","і п’ять жердин для брусів другого боку скинії, і п’ять жердин для брусів заднього боку позаду скинії, на захід;","а внутрішня жердина буде проходити посередині брусів від одного кінця до другого;","бруси ж обклади золотом, і кільця, для вкладання жердин, зроби з золота, і жердини обклади золотом.","І постав скинію за зразком, що показаний тобі на горі.","І зроби завісу з блакитної, пурпурової і червленої вовни і крученого висону; мистецькою роботою повинні бути зроблені на ній херувими;","і повісь її на чотирьох стовпах із ситима, обкладених золотом, з золотими гачками, на чотирьох срібних підніжках;","і повісь завісу на гачках і внеси туди за завісу ковчег одкровення; і буде завіса відокремлювати вам святилище від Святого Святих.","І поклади кришку на ковчег одкровення у Святому Святих.","І постав стіл поза завісою і світильник навпроти столу на стороні скинії на південь; стіл же постав на північній стороні [скинії].","І зроби завісу для входу в скинію з блакитної і пурпурової і червленої вовни і з крученого висону візерункової роботи;","і зроби для завіси п’ять стовпів із ситиму і обклади їх золотом; гачки до них золоті; і відлий для них п’ять підніжків мідних."],"x":{"1":"1.36.8|9.7.6","7":"1.36.14","10":"1.36.12","11":"1.36.18","14":"1.36.19","15":"1.36.20","30":"1.25.9","33":"1.40.3|75.9.3","34":"1.25.21|75.9.4","35":"1.40.22|75.9.2"}},{"v":["І зроби жертовник з дерева ситим довжиною п’ять ліктів і шириною п’ять ліктів, так щоб він був чотирикутний, і висотою у три лікті.","І зроби роги на чотирьох кутах його, так щоб роги виходили з нього; і обклади його міддю.","Зроби до нього горщики для висипання в них попелу, і лопатки, і чаші, і виделки, і вугільниці; усе приладдя зроби з міді.","Зроби до нього ґрати, рід сітки, з міді, і зроби на сітці, на чотирьох кутах її, чотири кільця мідних;","і поклади її по краях жертовника внизу, так щоб сітка була до половини жертовника.","І зроби жердини для жертовника, жердини із дерева ситим, і обклади їх міддю;","і вкладай жердини його в кільця, так щоб жердини були з обох боків жертовника, коли нести його.","Зроби його порожнім всередині, з дощок: як показано тобі на горі, так нехай зроблять [його].","Зроби двір скинії: з полуденної сторони на південь завіси для двору повинні бути з крученого висону довжиною у сто ліктів з одного боку;","стовпів для них двадцять, і підніжків для них двадцять мідних; гачки на стовпах і зв’язки на них зі срібла.","Також і вздовж по північній стороні — завіси ста ліктів довжиною; стовпів для них двадцять, і підніжків для них двадцять мідних; гачки на стовпах і зв’язки на них [і підніжки їх] зі срібла.","В ширину ж двору з західного боку — завіси п’ятдесяти ліктів; стовпів для них десять, і підніжків до них десять.","І в ширину двору з переднього боку на схід — [завіси] п’ятдесяти ліктів; [стовпів для них десять, і підніжків для них десять].","До однієї сторони — завіси у п’ятнадцять ліктів [висотою], стовпів для них три, і підніжків для них три;","і до другої сторони завіси у п’ятнадцять [ліктів висотою], стовпів для них три, і підніжків для них три.","А для воріт двору завіса у двадцять ліктів [висотою] з блакитної і пурпурової і червленої вовни і з крученого висону візерункової роботи; стовпів для неї чотири, і підніжків до них чотири.","Усі стовпи навколо двору повинні бути з’єднані зв’язками зі срібла; гачки на них зі срібла, а підніжки до них з міді.","Довжина двору сто ліктів, а ширина скрізь — п’ятдесят, висота п’ять ліктів; завіси з крученого висону, а підніжки у стовпів з міді.","Усе приладдя скинії для усякого вживання в ній, і всі кілки її, і всі кілки двору — з міді.","І накажи синам Ізраїлевим, щоб вони приносили тобі єлей чистий, видавлений з маслин, для освітлення, щоб горів світильник у всякий час;","у скинії зібрання поза завісою, що перед ковчегом одкровення, буде запалювати його Аарон і сини його, від вечора до ранку, перед лицем Господнім. Це устав вічний для поколінь їх від синів Ізраїлевих."],"x":{"1":"1.35.16","2":"10.1.50","9":"1.38.9","16":"1.35.17","20":"3.8.2","21":"2.6.18|2.24.3|8.3.3"}},{"v":["І візьми до себе Аарона, брата твого, і синів його з ним, від середовища синів Ізраїлевих, щоб він був священиком Мені, Аарона і Надава, Авиуда, Єлеазара й Іфамара, синів Ааронових.","І зроби священний одяг Аарону, братові твоєму, для слави і краси.","І скажи всім мудрим серцем, яких Я наповнив духом премудрости [і розуміння], щоб вони зробили Аарону [священні] одежі для посвяти його, щоб він був священиком Мені.","Ось одяг, який вони повинні зробити: наперсник, ефод*, верхня риза, хітон* витканий, кидар* і пояс. Нехай зроблять священний одяг Аарону, братові твоєму, і синам його, щоб він був священиком Мені.","Нехай вони візьмуть золото, блакитну і пурпурову і червлену вовну і висон,","і зроблять ефод із золота, з блакитної, пурпурової і червленої вовни, і з крученого висону, мистецькою роботою.","У нього повинні бути на обох кінцях його два з’єднувальні нарамники, щоб він був зв’язаний.","І пояс ефода, що поверх нього, повинен бути однакової з ним роботи, з [чистого] золота, з блакитної, пурпурової і червленої вовни і з крученого висону.","І візьми два камені онікса і виріж на них імена синів Ізраїлевих:","шість імен їхніх на одному камені і шість імен останніх на іншому камені, за порядком народження їх;","через різчика на камені, що вирізьблює печаті, виріж на двох каменях імена синів Ізраїлевих; і встав їх у золоті гнізда","і поклади два камені ці на нарамники ефода: це камені на пам’ять синам Ізраїлевим; і буде Аарон носити імена їхні перед Господом на обох раменах своїх для пам’яті.","І зроби гнізда з [чистого] золота;","і [зроби] два ланцюжки з чистого золота, витими зроби їх роботою плетеною, і прикріпи кручені ланцюжки до гнізд [на нарамниках їх спереду].","Зроби наперсник судний майстерною роботою; зроби його такою самою роботою, як ефод: із золота, з блакитної, пурпурової і червленої вовни і з крученого висону зроби його;","він повинен бути чотирикутний, подвійний, у п’ядь довжиною і в п’ядь шириною;","і встав у нього оправлені камені в чотири ряди; поряд: рубін, топаз, смарагд, — це один ряд;","другий ряд: карбункул, сапфір і алмаз;","третій ряд: яхонт, агат і аметист;","четвертий ряд: хризоліт, онікс і яспис; у золоті гнізда повинні бути вставлені вони.","Цих каменів повинно бути дванадцять, за числом [дванадцяти імен] синів Ізраїлевих [на двох раменах його], за іменами їх [і за народженням їх]; на кожнім, як на печаті, повинно бути вирізано по одному імені з числа дванадцяти колін.","До наперсника зроби ланцюжки кручені плетеної роботи з чистого золота;","і зроби до наперсника два кільця з золота і прикріпи два [золотих] кільця до двох країв наперсника;","і вдінь два плетені ланцюжки з золота в обидва кільця з [обох] кінців наперсника,","а два кінці двох ланцюжків прикріпи до двох гнізд і прикріпи до нарамників ефода з лицевої сторони його;","ще зроби два кільця золотих і прикріпи їх до двох інших кінців наперсника, на тій стороні, що лежить до ефода в середину;","також зроби два кільця золотих і прикріпи їх до двох нарамників ефода знизу, з лицевої сторони його, біля з’єднання його, над поясом ефода;","і прикріплять наперсник кільцями його до кілець ефода шнуром з блакитної вовни, щоб він був над поясом ефода, і щоб не спадав наперсник з ефода.","І буде носити Аарон імена синів Ізраїлевих на наперснику судному біля серця свого, коли буде входити у святилище, для постійної пам’яті перед Господом. [І поклади на наперсник судний кручені ланцюжки, поклади на обидва кінці наперсника, і поклади обидва гнізда на обох плечах на нарамнику з лиця.]","На наперсник судний поклади урим і тумим, і вони будуть біля серця Ааронового, коли буде він входити [у святилище] перед лице Господнє; і буде Аарон завжди носити суд синів Ізраїлевих біля серця свого перед лицем Господнім.","І зроби верхню ризу до ефода всю блакитного кольору;","посеред неї повинен бути отвір для голови; біля отвору її навколо повинна бути обшивка виткана, подібно до отвору у броні, щоб не дерлося;","на подолі її зроби яблука з ниток блакитного, яхонтового, пурпурового і червленого кольору [і з крученого висону], навколо по подолу її; [такого вигляду яблука і] дзвоники золоті між ними навкруги:","золотий дзвоник і яблуко, золотий дзвоник і яблуко, по подолу верхньої ризи навкруги;","вона буде на Аароні в служінні, щоб чутним був від нього звук, коли він буде входити у святилище перед лице Господнє і коли буде виходити, щоб йому не вмерти.","І зроби поліровану дощечку з чистого золота, і виріж на ній, як вирізують на печатці: «Святиня Господня»,","і прикріпи її шнуром блакитного кольору до кидара, так щоб вона була на передній стороні кидара;","і буде вона на чолі Аароновому, і понесе на собі Аарон недоліки приношень, що посвячуються від синів Ізраїлевих, і всіх дарів, які вони приносять; і буде вона безперестанно на чолі його, для благовоління Господнього до них.","І зроби хітон з висону і кидар з висону і зроби пояс візерунчастої роботи;","зроби і синам Аароновим хітони, зроби їм пояси, і головні пов’язки зроби їм для слави і краси,","і зодягни в них Аарона, брата твого, і синів його з ним, і помаж їх, і наповни руки їх, і посвяти їх, і вони будуть священиками Мені.","І зроби їм нижній одяг лляний, для прикриття тілесної наготи від стегон до гомілок,","і хай буде він на Аароні і на синах його, коли будуть вони входити у скинію забрання, або приступати до жертовника для служіння у святилищі, щоб їм не навести [на себе] гріха і не померти. Це устав вічний, [нехай буде] для нього і для нащадків його після нього."],"x":{"1":"75.5.4|1.6.23","2":"1.31.10","3":"1.31.3","17":"29.18.24|76.21.19","25":"1.28.7","30":"2.8.8|3.27.21","35":"30.45.11","41":"2.8.30|6.17.5"},"n":{"4":["Короткий одяг.","Довгий нижній одяг.","Прикраса для голови."]}},{"v":["Ось що повинен ти звершити над ними, щоб посвятити їх у священики Мені: візьми одного тельця з волів, і двох баранів без вад,","і хлібів прісних, і опрісноків, змішаних з єлеєм, і коржів прісних, помазаних єлеєм: з борошна пшеничного зроби їх,","і поклади їх в один кошик, і принеси їх у кошику, і разом тельця і двох баранів.","Аарона ж і синів його приведи до входу в скинію зібрання і омий їх водою.","І візьми [священний] одяг, і зодягни Аарона в хітон і у верхню ризу, в ефод і в наперсник, і підпережи його по ефоду;","і поклади йому на голову кидар і закріпи діадему святині на кидарі;","і візьми єлей помазання, і полий йому на голову, і помаж його.","І приведи також синів його і зодягни їх у хітони;","і підпережи їх поясом, Аарона і синів його, і поклади на них пов’язки і буде їм належати священство за уставом навік; і наповни руки Аарона і синів його.","І приведи тельця перед скинію зібрання, і покладуть Аарон і сини його руки свої на голову тельця [перед Господом біля дверей скинії зібрання];","і заколи тельця перед лицем Господнім при вході у скинію зібрання;","візьми крови тельця і поклади перстом твоїм на роги жертовника, а всю [іншу] кров вилий біля жертовника;","візьми весь жир, що вкриває нутрощі, і сальник з печінки, і обидві нирки і жир, що на них, і покади на жертовнику;","а м’ясо тельця і шкуру його і нечистоти його спали на вогні поза станом: це — жертва за гріх.","І візьми одного барана, і покладуть Аарон і сини його руки свої на голову барана;","і заколи барана, і візьми крови його, і покропи на жертовник з усіх боків;","розсічи барана на частини, вимий [у воді] нутрощі його і гомілки його, і поклади їх на розсічені частини його і на голову його;","і спали всього барана на жертовнику. Це всепалення Господу, пахощі приємні, жертва Господу.","Візьми й іншого барана, і покладуть Аарон і сини його руки свої на голову барана;","і заколи барана, і візьми крови його, і поклади на край правого вуха Ааронового і на край правого вуха синів його, і на великий палець правої руки їх, і на великий палець правої ноги їх; і покропи кров’ю на жертовник з усіх боків;","і візьми крови, яка на жертовнику, і єлею помазання, і покропи на Аарона і на одежу його, і на синів його, і на одежу синів його з ним, — і будуть освячені, він і одяг його, і сини його й одяг їхній з ними.","І візьми від барана жир і курдюк, і жир, що покриває нутрощі, і сальник з печінки, й обидві нирки і жир, який на них, праве плече [тому що це баран приношення священства],","і один круглий хліб, один корж на єлеї й один опріснок з кошика, що перед Господом,","і поклади усе на руки Аарону і на руки синам його, і принеси це, потрясаючи перед лицем Господнім;","і візьми це з рук їхніх і спали на жертовнику з усепаленням, для пахощів перед Господом: це жертва Господу.","І візьми груди від барана приношення, який для Аарона, і принеси їх, потрясаючи перед лицем Господнім, — і це буде твоя частка;","і освяти груди приношення, якими потрясав, і плече приношення, яке було вознесене, від барана приношення, який для Аарона і для синів його, —","і буде це Аарону і синам його в частку вічну від синів Ізраїлевих, бо це — приношення; приношення повинно бути від синів Ізраїлевих при мирних жертвах [синів Ізраїлевих], приношення їхньому Господу.","А священний одяг, що для Аарона, перейде після нього до синів його, щоб у ньому помазувати їх і вручати їм священство;","сім днів повинен облачатися в них [великий] священик із синів його, який заступає його місце, і буде входити у скинію зібрання для служіння у святилищі.","Барана ж приношення візьми і звари м’ясо його на місці святому;","і нехай з’їдять Аарон і сини його м’ясо барана цього з кошика, біля дверей скинії зібрання,","бо через це здійснено очищення для вручення їм священства і для посвячення їх; сторонній не повинен їсти цього, тому що це святиня;","якщо залишиться від м’яса приношення і від хліба до ранку, то спали залишок на вогні: не слід їсти його, бо це святиня.","І вчини з Аароном і з синами його в усьому так, як Я повелів тобі; сім днів наповнюй руки їх.","І тельця за гріх принось кожного дня для очищення, і жертву за гріх звершуй на жертовнику для очищення його, і помаж його для освячення його;","сім днів очищай жертовник, і освяти його, і буде жертовник святинею великою: усе, що доторкається до жертовника, освятиться.","Ось що будеш ти приносити на жертовнику: двох агнців однолітніх [без вад] кожного дня постійно [у жертву повсякчасну];","одного агнця принось уранці, а другого агнця принось увечері,","і десяту частину ефи пшеничного борошна, змішаної з чвертю гина битого єлею, а для узливання чверть гина вина, для одного агнця;","другого агнця принось увечері: з борошняним даром, подібним ранковому, і з таким самим узливанням принось його для пахощів приємних, у жертву Господу.","Це — всепалення постійне в роди ваші перед дверима скинії зібрання перед Господом, де буду відкриватися вам, щоб говорити з тобою;","там буду відкриватися синам Ізраїлевим, і освятиться місце це славою Моєю.","І освячу скинію зібрання і жертовник; і Аарона і синів його освячу, щоб вони священнодіяли Мені;","і буду жити серед синів Ізраїлевих, і буду їм Богом,","і дізнаються, що Я Господь, Бог їхній, Який вивів їх із землі Єгипетської, щоб Мені жити серед них. Я Господь, Бог їхній."],"x":{"1":"2.9.2","4":"1.30.20|1.40.12","9":"1.28.41","10":"2.1.3","13":"2.3.3","14":"2.4.12|3.19.5|75.13.11","15":"2.8.18","16":"75.9.12:19","19":"2.1.4","21":"1.30.30","22":"2.3.3|2.7.37","24":"1.35.22","26":"2.8.29","28":"1.27.21","32":"2.8.31|2.24.9|50.12.4|51.2.26|52.6.4","38":"3.28.3","39":"3.28.4","43":"25.77.60|36.37.27|48.2.10","45":"2.26.12|64.6.16"}},{"v":["І зроби жертовник для приношення кадіння, з дерева ситим зроби його:","довжина йому лікоть, і ширина йому лікоть; він повинен бути чотирикутний; а висота його два лікті; з нього повинні виходити роги його;","обклади його чистим золотом, верх його і боки його кругом, і роги його; і зроби до нього золотий вінець навколо;","під вінцем його на двох кутах його зроби два кільця з [чистого] золота; зроби їх із двох сторін його; і будуть вони вмістилищем для жердин, щоб носити його на них;","жердини зроби з дерева ситим і обклади їх золотом.","І постав його перед завісою, яка перед ковчегом одкровення, навпроти кришки, що на ковчезі одкровення, де Я буду відкриватися тобі.","На ньому Аарон буде курити запашним курінням; щоранку, коли він готує лампади, буде курити ним;","і коли Аарон запалює лампади ввечері, він буде курити ним: це — повсякчасне куріння перед Господом в роди ваші,","Не приносьте на ньому ніякого іншого куріння, ні всепалення, ні приношення хлібного, й узливання не зливайте на нього.","І буде звершувати Аарон очищення над рогами його один раз на рік; кров’ю очищувальної жертви за гріх він буде очищати його один раз на рік в роди ваші. Це святиня велика в Господа.","І сказав Господь Мойсеєві, кажучи:","коли будеш робити перелік синів Ізраїлевих при перегляді їх, то нехай кожен дасть викуп за душу свою Господу при переліку їх, і не буде між ними моровиці згубної при переліку їх;","всякий, хто включається в перелік, повинен давати половину сикля, сикля священного; у сиклі двадцять гер: півсикля приношення Господу;","всякий, хто включається в перелік від двадцяти років і вище, повинен давати приношення Господу;","багатий не більше і бідний не менше півсикля повинні давати для приношення Господу, для викупу душ ваших;","і візьми срібло викупу від синів Ізраїлевих і вживай його на служіння скинії зібрання; і буде це для синів Ізраїлевих у пам’ять перед Господом, для викуплення душ ваших.","І сказав Господь Мойсеєві, говорячи:","зроби умивальник мідний для обмивання і підніжжя його мідне, і постав його між скинією зібрання і між жертовником, і налий в нього води;","і нехай Аарон і сини його обмивають з нього руки свої і ноги свої;","коли вони повинні входити в скинію зібрання, нехай вони обмиваються водою, щоб їм не померти; або коли повинні приступати до жертовника для служіння, для жертвоприношення Господу,","нехай вони обмивають руки свої і ноги свої водою, щоб їм не померти; і буде їм це уставом вічним, йому і нащадкам його в роди їх.","І сказав Господь Мойсеєві, говорячи:","візьми собі найкращих запашних речовин: смирни самоточної п’ятсот [сиклів], кориці запашної половину проти того, двісті п’ятдесят, тростини запашної двісті п’ятдесят,","касії п’ятсот сиклів, по сиклю священному, й олії оливкової гин;","і зроби із цього миро для священного помазання, масть складену, мистецтвом того, хто складає масті: це буде миро для священного помазання;","і помаж ним скинію зібрання і ковчег [скинії] одкровення,","і стіл і все приладдя його, і світильник і все приладдя його, і жертовник куріння,","і жертовник всепалення й усе приладдя його, й умивальник і підніжжя його;","і освяти їх, і буде святиня велика: усе, що доторкається до них, освятиться;","помаж й Аарона і синів його і посвяти їх, щоб вони були священиками Мені.","А синам Ізраїлевим скажи: це буде в Мене миро священного помазання в роди ваші;","тіла інших людей не слід помазувати ним, і за складом його не робіть [самі собі] подібного йому; воно — святиня: святинею повинно бути для вас;","хто складе подібне йому або хто помаже ним стороннього, той знищиться з народу свого.","І сказав Господь Мойсеєві: візьми собі запашних речовин: стакти, ониха, халвана запашного і чистого ливану, усього половину,","і зроби з них мистецтвом того, хто складає масті, курильну сполуку, стерту, чисту, святу,","і стовчи її дрібно, і поклади її перед ковчегом одкровення в скинії зібрання, де Я буду відкриватися тобі: це буде святиня велика для вас;","куріння, зробленого за цією сполукою, не робіть собі: святинею нехай буде воно у тебе для Господа;","хто зробить подібне, щоб курити ним, [душа та] знищиться з народу свого."],"x":{"3":"3.4.11","6":"1.25.22","7":"8.3.14|25.140.2|52.1.9","9":"2.10.1","10":"2.16.2|75.9.7:13","12":"3.1.2","13":"2.27.25|3.3.47|36.45.12","15":"3.15.19|4.12.6|17.12.44","18":"1.35.16","23":"28.4.14|36.27.22","30":"58.2.20:27","35":"1.35.15|12.9.30"}},{"v":["І сказав Господь Мойсеєві, говорячи:","дивись, Я призначаю саме Веселеїла, сина Урієвого, сина Орового, з коліна Іудиного;","і Я сповнив його Духом Божим, мудрістю, розумінням, знанням і всіляким мистецтвом,","виробляти з золота, срібла і міді, [з блакитної, пурпурової і червленої вовни і з крученого висону],","різати камені для вставлення і різати дерево для всякої справи;","і ось, Я даю йому помічником Аголиава, сина Ахисамахового, з коліна Данового, і в серце всякого мудрого вкладу мудрість, щоб вони зробили все, що Я повелів тобі:","скинію зібрання і ковчег одкровення і кришку на нього, й усе приладдя скинії,","і стіл і [все] приладдя його, і світильник з чистого золота і все приладдя його, і жертовник куріння,","і жертовник всепалення й усе приладдя його, й умивальник і підніжжя його,","й одежі службові й одяг священний Аарону священику, й одежі синам його, для священнослужіння,","й єлей помазання і куріння запашне для святилища: усе так, як Я повелів тобі, вони зроблять.","І сказав Господь Мойсеєві, говорячи:","скажи синам Ізраїлевим так: суботи Мої дотримуйте, бо це — знамення між Мною і вами в роди ваші, щоб ви знали, що Я Господь, Який освячує вас;","і додержуйте суботу, тому що вона свята для вас: хто осквернить її, той нехай буде відданий на смерть; хто стане в цей день робити справи, душа та повинна бути знищеною із середовища народу свого;","шість днів нехай роблять справи, а в сьомий — субота спокою, посвячена Господу: усякий, хто робить справи в день суботній, нехай буде відданий на смерть;","і нехай зберігають сини Ізраїлеві суботу, святкуючи субботу в роди свої, як завіт вічний;","це — знамення між Мною і синами Ізраїлевими повік, тому що в шість днів сотворив Господь небо і землю, а в день сьомий спочив і покоївся.","І коли [Бог] перестав говорити з Мойсеєм на горі Синаї, дав йому дві скрижалі одкровення, скрижалі кам’яні, на яких написано було перстом Божим."],"x":{"2":"1.35.30","3":"10.7.14","6":"1.35.34","7":"1.35.11","13":"1.20.8|36.20.12","14":"3.15.35|0.17.14","15":"1.20.9","17":"0.1.31|0.2.1-2|1.20.11|75.4.4","18":"1.32.16|1.34.29|4.9.10"}},{"v":["Коли народ побачив, що Мойсей довго не сходить з гори, то зібрався до Аарона і сказав йому: встань і зроби нам бога, який ішов би перед нами, тому що з цією людиною, з Мойсеєм, який вивів нас із землі Єгипетської, не знаємо, що сталося.","І сказав їм Аарон: вийміть золоті серги, що у вухах ваших дружин, ваших синів і ваших дочок, і принесіть до мене.","І весь народ вийняв золоті серги з вух своїх і принесли до Аарона.","Він узяв їх з рук їхніх, і зробив з них відлитого тельця, і обробив його різцем. І сказали вони: ось бог твій, Ізраїлю, що вивів тебе із землі Єгипетської!","Побачивши це, Аарон поставив перед ним жертовник, і проголосив Аарон, говорячи: завтра свято Господу.","На другий день вони встали рано і принесли всепалення і привели жертви мирні: і сів народ їсти й пити, а після став грати.","І сказав Господь Мойсеєві: поспішай зійти [звідси], тому що розбестився народ твій, який ти вивів із землі Єгипетської;","швидко ухилились вони від шляху, що Я заповідав їм: зробили собі відлитого тельця і поклонилися йому, і принесли йому жертви і сказали: ось бог твій, Ізраїлю, що вивів тебе із землі Єгипетської!","І сказав Господь Мойсею: Я бачу народ цей, і ось, народ він — жорстокосердий;","отже, залиш Мене, нехай запалає гнів Мій на них, і винищу їх, і породжу численний народ від тебе.","Але Мойсей став благати Господа, Бога свого, і сказав: нехай не розпалюється, Господи, гнів Твій на народ Твій, який Ти вивів із землі Єгипетської силою великою і рукою міцною,","щоб єгиптяни не говорили: на погибель Він вивів їх, щоб убити їх у горах і винищити їх з лиця землі; відверни полум’яний гнів Твій і відміни знищення народу Твого;","пом’яни Авраама, Ісаака й Ізраїля [Якова], рабів Твоїх, яким клявся Ти Собою, говорячи: примножуючи розмножу сíм’я ваше, як зірки небесні, і всю землю цю, про яку Я сказав, дам сімені вашому, і будуть володіти [нею] вічно.","І відмінив Господь зло, про яке сказав, що наведе його на народ Свій.","І обернувся і зійшов Мойсей з гори; у руці його були дві скрижалі одкровення [кам’яні], на яких написано було з обох боків: і на одній і на другій стороні написано було;","скрижалі були ділом Божим, і письмена, написані на скрижалях, були письменами Божими.","І почув Ісус голос народу, який шумів, і сказав Мойсеєві: воєнний крик у стані.","Але [Мойсей] сказав: це не крик тих, що перемагають, і не волання тих, кого перемагають; я чую голос тих, що співають.","Коли ж він наблизився до стану і побачив тельця і танці, тоді він розпалився гнівом і кинув з рук своїх скрижалі і розбив їх під горою;","і взяв тельця, якого вони зробили, і спалив його у вогні, і стер у порох, і розсипав по воді, і дав її пити синам Ізраїлевим.","І сказав Мойсей Аарону: що зробив тобі народ цей, що ти ввів його в гріх великий?","Але Аарон сказав [Мойсеєві]: хай не розпалюється гнів господаря мого; ти знаєш цей народ, що він буйний.","Вони сказали мені: зроби нам бога, що йшов би перед нами; тому що з Мойсеєм, з цим чоловіком, який вивів нас із землі Єгипетської, не знаємо, що сталося.","І я сказав їм: у кого є золото, зніміть із себе. [Вони зняли] і віддали мені; я кинув його у вогонь, і вийшов цей телець.","Мойсей побачив, що це народ розгнузданий, бо Аарон допустив його до розгнузданости, до посоромлення перед ворогами його.","І став Мойсей у воротах стану і сказав: хто Господній, [іди] до мене! І зібралися до нього всі сини Левіїні.","І він сказав їм: так говорить Господь Бог Ізраїлів: покладіть кожен свій меч на стегно своє, пройдіть по стану від воріт до воріт і назад, і вбивайте кожен брата свого, кожен друга свого, кожен ближнього свого.","І зробили сини Левіїни за словом Мойсея: і загинуло в той день з народу близько трьох тисяч чоловік.","Бо Мойсей сказав [їм]: сьогодні присвятите руки ваші Господу, кожен у сині своєму і браті своєму, нехай пошле Він вам сьогодні благословення.","На другий день сказав Мойсей народу: ви зробили великий гріх; отже, я зійду до Господа, чи не загладжу гріха вашого.","І повернувся Мойсей до Господа і сказав: о, [Господи!] народ цей зробив великий гріх: зробив собі золотого бога;","прости їм гріх їхній, а якщо ні, то згладь і мене з книги Твоєї, в яку Ти вписав.","Господь сказав Мойсею: того, хто згрішив переді Мною, згладжу з книги Моєї;","отже, йди, [зійди,] веди народ цей, куди Я сказав тобі; ось ангел Мій піде перед тобою, і в день відвідання Мого Я відвідаю їх за гріх їхній.","І уразив Господь народ за зробленого тельця, якого зробив Аарон."],"x":{"1":"54.7.40","3":"4.9.16","4":"25.105.19|10.12.28|17.9.18","6":"63.10.7","7":"4.9.12","8":"10.12.28","10":"4.9.14","11":"25.105.23","12":"3.14.13:15","13":"0.12.7|0.15.7|0.48.16|25.104.8-10","16":"1.31.18|4.9.10","17":"1.24.13","19":"4.9.17","26":"0.34.20","27":"4.33.9","29":"4.33.10","32":"62.9.3|25.68.29|67.4.3|76.3.5","34":"1.14.19|1.33.2|3.14.18"}},{"v":["І сказав Господь Мойсеєві: піди, йди звідси ти і народ, який ти вивів із землі Єгипетської, у землю, про яку Я клявся Аврааму, Ісааку і Якову, говорячи: нащадкам твоїм дам її;","і пошлю перед тобою ангела [Мого], і прожену хананеїв, аморреїв, хеттеїв, ферезеїв, [гергесеїв,] євеїв та ієвусеїв,","[і введе він вас] у землю, де тече молоко і мед; бо Сам не піду серед вас, щоб не погубити Мені вас на шляху, тому що ви народ жорстокосердий.","Народ, почувши грізне слово це, заридав, і ніхто не поклав на себе прикрас своїх.","Тому що Господь сказав Мойсеєві: скажи синам Ізраїлевим: ви народ жорстокосердий; якщо Я піду серед вас, то в одну мить винищу вас; отже, зніміть з себе прикраси свої; Я подивлюся, що Мені робити з вами.","Сини Ізраїлеві зняли із себе прикраси свої біля гори Хорива.","Мойсей же взяв і поставив собі намет поза станом, удалині від стану, і назвав його скинією зібрання; і кожен, хто шукає Господа, приходив до скинії зібрання, що знаходилася поза станом.","І коли Мойсей виходив до скинії, весь народ вставав, і ставав кожен біля входу у свій намет і дивився услід Мойсею, доки він не входив у скинію.","Коли ж Мойсей входив у скинію, тоді спускався стовп хмарний і ставав біля входу в скинію, і [Господь] говорив з Мойсеєм.","І бачив весь народ стовп хмарний, що стояв при вході в скинію; і вставав увесь народ, і поклонявся кожен біля входу в намет свій.","І говорив Господь з Мойсеєм лицем до лиця, ніби говорив хто з другом своїм; і він повертався до стану, а служитель його Ісус, син Навинів, юнак, не відлучався від скинії.","Мойсей сказав Господу: ось, Ти говориш мені: веди народ цей, а не відкрив мені, кого пошлеш зі мною, хоча Ти сказав: «Я знаю тебе на ім’я і ти придбав благовоління в очах Моїх»;","отже, якщо я придбав благовоління в очах Твоїх, то молю: відкрий мені шлях Твій, щоб я пізнав Тебе, щоб придбати благовоління в очах Твоїх; і думку, що ці люди Твій народ.","[Господь] сказав [йому]: Сам Я піду [перед тобою] і введу тебе у спокій.","[Мойсей] сказав Йому: якщо не підеш Ти Сам [з нами], то і не виводь нас звідси,","бо з чого дізнатися, що я і народ Твій придбали благовоління в очах Твоїх? чи не з того, коли Ти підеш з нами? тоді я і народ Твій будемо славніше за всякий народ на землі.","І сказав Господь Мойсеєві: і те, про що ти говорив, Я зроблю, тому що ти придбав благовоління в очах Моїх, і Я знаю тебе на ім’я.","[Мойсей] сказав: покажи мені славу Твою.","І сказав [Господь Мойсею]: Я проведу перед тобою всю славу Мою і проголошу ім’я Ієгови перед тобою, і кого помилувати — помилую, кого пожаліти — пожалію.","І потім сказав Він: лиця Мого не можна тобі побачити, тому що людина не може побачити Мене і залишитися в живих.","І сказав Господь: ось місце у Мене, стань на цій скелі;","коли ж буде проходити слава Моя, Я поставлю тебе в розщелині скелі і покрию тебе рукою Моєю, доки не пройду;","і коли зніму руку Мою, ти побачиш Мене ззаду, а лице Моє не буде видиме [тобі]."],"x":{"1":"0.50.24|3.32.11","2":"1.23.23|4.7.1|5.24.11","3":"1.34.9","5":"32.6.26|39.1.8|42.3.6","9":"4.31.15","11":"3.12.7-8|4.34.10|30.45.3","14":"4.4.37","17":"72.2.19","19":"62.9.15","20":"6.13.22|37.10.8|71.6.16"}},{"v":["І сказав Господь Мойсеєві: витеши собі дві скрижалі кам’яні, подібні до попередніх, [і зійди до Мене на гору,] і Я напишу на цих скрижалях слова, які були на попередніх скрижалях, які ти розбив;","і будь готовим до ранку, і зійди вранці на гору Синай, і постань переді Мною там на вершині гори;","але ніхто не повинен підніматися з тобою, і ніхто не повинен показуватися на всій горі; навіть худоба, дрібна і велика, не повинна пастися біля гори цієї.","І витесав Мойсей дві скрижалі кам’яні, подібні до попередніх, і, вставши рано-вранці, зійшов на гору Синай, як повелів йому Господь; і взяв у руки свої дві скрижалі кам’яні.","І зійшов Господь у хмарі, і зупинився там поблизу нього, і проголосив ім’я Ієгови.","І пройшов Господь перед лицем його і проголосив: Господь, Господь, Бог чоловіколюбний і милосердий, довготерпеливий і многомилостивий і істинний,","що зберігає [правду і подає] милість у тисячі родів, Який прощає провину і злочин і гріх, але не залишає без покарання, Який карає провину батьків у дітях і в дітях дітей до третього і четвертого роду.","Мойсей одразу ж упав на землю і поклонився [Богу]","і сказав: якщо я придбав благовоління в очах Твоїх, Владико, то хай піде Владика посеред нас; бо народ цей жорстокосердий; прости беззаконня наші і гріхи наші і вчини нас насліддям Твоїм.","І сказав [Господь Мойсеєві]: ось, Я укладаю завіт: перед усім народом твоїм сотворю чудеса, яких не було по всій землі і ні в яких народів; і побачить весь народ, серед якого ти перебуваєш, діло Господа; бо страшним буде те, що Я зроблю для тебе;","збережи те, що повеліваю тобі нині: ось, Я виганяю від лиця твого аморреїв, хананеїв, хеттеїв, ферезеїв, евеїв, [гергесеїв] та ієвусеїв;","дивися, не вступай у союз з жителями тієї землі, у яку ти ввійдеш, щоб вони не зробилися сіттю серед вас.","Жертовники їхні зруйнуйте, стовпи їхні розтрощіть, вирубайте священні гаї їхні, [і статуї богів їхніх спаліть вогнем],","тому що ти не повинен поклонятися богові іншому, крім Господа [Бога], тому що ім’я Його — ревнитель; Він Бог ревнитель.","Не вступай у союз із жителями тієї землі, щоб, коли вони будуть блудодіяти услід богам своїм і приносити жертви богам своїм, не запросили і тебе, і ти не спожив би жертви їхньої;","і не бери з дочок їхніх дружин синам своїм [і дочок своїх не давай заміж за синів їхніх], щоб дочки їхні, блудодіючи вслід богам своїм, не ввели і синів твоїх у блуд вслід богам своїм.","Не роби собі богів відлитих.","Свята опрісноків дотримуй: сім днів їж прісний хліб, як Я повелів тобі, у призначений час місяця Авива, тому що в місяці Авиві вийшов ти з Єгипту.","Усе, що розкриває утробу, Мені, як і вся худоба твоя чоловічої статі, що розкриває утробу, з волів і овець;","первородне з ослів замінюй агнцем, а якщо не заміниш, то викупи його; усіх первістків із синів твоїх викуповуй; нехай не з’являються перед лице Моє з порожніми руками.","Шість днів працюй, а в сьомий день спочивай; спочивай і під час сівби і жнив.","І свято седмиць роби, свято початків жнив пшениці і свято збирання плодів наприкінці року;","тричі на рік повинна з’являтись уся чоловіча стать твоя перед лице Владики, Господа Бога Ізраїлевого,","бо Я прожену народи від лиця твого і поширю межі твої, і ніхто не зажадає землі твоєї, якщо ти будеш з’являтися перед лице Господа Бога твого тричі на рік.","Не виливай крови жертви Моєї на квасне, і жертва свята Пасхи не повинна переночувати до ранку.","Найперші плоди землі твоєї принеси в дім Господа Бога твого. Не вари козеня в молоці матері його.","І сказав Господь Мойсеєві: напиши собі слова ці, тому що в цих словах Я укладаю завіт з тобою і з Ізраїлем.","І пробув там [Мойсей] у Господа сорок днів і сорок ночей, хліба не їв і води не пив; і написав [Мойсей] на скрижалях слова завіту, десятислів’я.","Коли сходив Мойсей з гори Синаю, і дві скрижалі одкровення були в руці у Мойсея при сході його з гори, то Мойсей не знав, що лице його стало сяяти промінням від того, що Бог говорив з ним.","І побачив Мойсея Аарон і всі сини Ізраїлеві, і ось, лице його сяє, і боялися підійти до нього.","І покликав їх Мойсей, і прийшли до нього Аарон і всі начальники громади, і розмовляв Мойсей з ними.","Після цього наблизилися [до нього] всі сини Ізраїлеві, і він заповідав їм усе, що говорив йому Господь на горі Синаї.","І коли Мойсей перестав розмовляти з ними, то поклав на лице своє покривало.","Коли ж входив Мойсей перед лице Господа, щоб говорити з Ним, тоді знімав покривало, доки не виходив; а вийшовши, переказував синам Ізраїлевим усе, що заповідано було [йому від Господа].","І бачили сини Ізраїлеві, що сяє лице Мойсеєве, і Мойсей знову накладав покривало на лице своє, доки не входив говорити з Ним."],"x":{"1":"4.10.1","2":"1.33.21","3":"1.19.12","4":"4.10.3","5":"1.33.19","6":"25.85.15|39.2.13|42.4.2","7":"1.20.6|4.5.10|32.32.18","8":"8.24.9","9":"4.9.13","12":"4.7.2","13":"1.23.24","14":"1.20.5","15":"1.23.32|4.7.2","16":"10.11.1|4.7.3","17":"1.20.3","18":"1.12.2:15","19":"1.13.2|1.22.29|36.44.30|52.2.23","20":"1.13.13","21":"1.20.9","22":"4.16.10","23":"1.23.17|4.16.16","25":"1.12.10|1.23.18","26":"1.23.19|4.14.21","27":"1.24.4","28":"1.24.18|4.9.9:18","30":"64.3.7","32":"1.35.1","33":"64.3.13"}},{"v":["І зібрав Мойсей усю громаду синів Ізраїлевих і сказав їм: ось що заповідав Господь чинити:","шість днів робіть справи, а день сьомий повинен бути у вас святим, субота спокою Господу: всякий, хто буде робити в цей день справи, відданий буде смерті;","не запалюйте вогню в усіх житлах ваших в день суботи. [Я Господь.]","І сказав Мойсей усій громаді синів Ізраїлевих: ось що заповів Господь:","зробіть від себе приношення Господу: кожний за ревністю нехай принесе приношення Господу, золото, срібло, мідь,","вовну блакитного, пурпурового і червленого кольору, і висон [кручений], і козячу вовну,","шкури баранячі червоні, і шкури сині, і дерево ситим,","і єлей для світильника, і пахощі для єлея помазання і для запашних курінь,","камінь онікс і камені вставні для ефода і наперсника.","І кожен з вас, хто мудрий серцем, нехай прийде і зробить усе, що повелів Господь:","скинію і покров її і верхню покришку її, гачки і бруси її, жердини її, стовпи її і підніжжя її,","ковчег і жердини його, кришку і завісу для перегородки, [і завіси двору і стовпи його, і камені смарагдові і фіміам і єлей помазання,]","стіл і жердини його й усе приладдя його, і хліби предкладення,","і світильник для освітлення з [усім] приладдям його, і лампади його і єлей для освітлення,","і жертовник для кадіння і жердини його, і єлей помазання, і запашні куріння, і завісу до входу в скинію,","жертовник всепалення і ґрати мідні для нього, і жердини його й усе приладдя його, умивальник і підніжжя його,","завіси двору, стовпи його і підніжжя їх, і завісу при вході в двір,","кілки скинії, і кілки двору і шнури їх,","одяг службовий для служіння у святилищі, і священні одежі Аарону священику й одяг синам його для священнодійства.","І пішла вся громада синів Ізраїлевих від Мойсея.","І приходили всі, кого тягнуло до того серце, і всі, кого надихав дух, і приносили приношення Господу для влаштування скинії зібрання і для всіх потреб її і для [усіх] священних одеж;","і приходили чоловіки з дружинами, і всі за велінням серця приносили кільця, серги, персні і підвіски, усякі золоті речі, кожен, хто тільки хотів приносити золото Господу;","і кожен, у кого була вовна блакитного, пурпурового і червленого кольору, висон і козяча вовна, шкури баранячі червоні і шкури сині, приносив їх;","і кожен, хто жертвував срібло або мідь, приносив це в дар Господу; і кожен, у кого було дерево ситим, приносив це на всяку потребу для скинії;","і всі жінки, мудрі серцем, пряли своїми руками і приносили пряжу блакитного, пурпурового і червленого кольору і висон;","і всі жінки, яких тягнуло серце, що вміли прясти, пряли козячу вовну;","князі ж приносили камінь онікс і камені вставні для ефода і наперсника,","також і пахощі, і єлей для світильника і складові для єлея помазання і для запашних курінь;","і всі чоловіки і дружини з синів Ізраїлевих, яких тягло серце принести на всяке діло, яке Господь через Мойсея повелів зробити, приносили добровільний дар Господу.","І сказав Мойсей синам Ізраїлевим: дивіться, Господь призначив саме Веселеїла, сина Урії, сина Ора, з коліна Іудиного,","і сповнив його Духом Божим, мудрістю, розумінням, віданням і всяким мистецтвом,","складати майстерні тканини, працювати з золотом, сріблом і міддю,","і різати камені для вставлення, і різати дерево, і робити всяку художню роботу;","і здібність учити інших вклав у серце його, його й Аголіава, сина Ахисамахового, з коліна Данового;","він наповнив серце їх мудрістю, щоб виконувати всяку роботу [для святилища] різьбяра і мистецького ткача, і гаптівника по блакитній, пурпуровій, червленій і висоновій тканині, і ткачів, що роблять усяку роботу і складають мистецькі тканини."],"x":{"1":"1.34.32","2":"1.20.9|1.31.14","3":"1.16.23","5":"1.25.2","11":"1.25.8","13":"1.25.23","14":"1.25.31","15":"1.30.1","16":"1.27.1","17":"1.27.9","19":"1.28.2","22":"3.18.18","25":"26.31.19","30":"1.31.2","34":"1.31.6"}},{"v":["І стали працювати Веселеїл і Аголіав і всі мудрі серцем, кому Господь дав мудрість і розуміння, щоб уміти зробити всяку роботу, потрібну для святилища, як повелів Господь.","І покликав Мойсей Веселеїла й Аголіава і всіх мудрих серцем, яким Господь дав мудрість, і всіх, кого тягло серце приступити до роботи і працювати.","І взяли вони від Мойсея всі приношення, які принесли сини Ізраїлеві, на [усі] потреби святилища, щоб працювати. Між тим ще продовжували приносити до нього добровільні дари кожного ранку.","Тоді прийшли всі мудрі серцем, що виконували всякі роботи у святилищі, кожен від своєї роботи, якою хто займався,","і сказали Мойсеєві, говорячи: народ багато приносить, більше, ніж потрібно для робіт, які повелів Господь зробити.","І наказав Мойсей, і оголошено було у стані, щоб ні чоловік, ні жінка не робили уже нічого для приношення у святилище; і перестав народ приносити.","Запасу було доволі на всякі роботи, які належало зробити, і навіть залишилося.","І зробили всі мудрі серцем, що займалися роботою для скинії: десять покривал із крученого висону з блакитної, пурпурової і червленої вовни; і херувимів зробили на них мистецькою роботою;","довжина кожного покривала двадцять вісім ліктів, і ширина кожного покривала чотири лікті: усім покривалам одна міра.","І з’єднав він п’ять покривал одне з одним, й інші п’ять покривал з’єднав одне з одним.","І зробив петлі блакитного кольору на краю одного покривала, де воно з’єднується з іншим; так само зробив він і на краю останнього покривала, для з’єднання його з іншим;","п’ятдесят петель зробив він на одному покривалі, і п’ятдесят петель зробив на краю покривала, де воно з’єднується з іншим; петлі ці відповідали одна одній;","і зробив п’ятдесят гачків золотих, і гачками з’єднав одне покривало з іншим, і стала скинія одним цілим.","Потім зробив покривала з козячої вовни для покриття скинії: одинадцять покривал зробив таких;","довжиною покривало тридцять ліктів, і шириною покривало чотири лікті: одинадцятьом покривалам міра одна.","І з’єднав він п’ять покривал окремо і шість покривал окремо.","І зробив п’ятдесят петель на краю покривала крайнього, де воно з’єднується з іншим, і п’ятдесят петель зробив на краю покривала, що з’єднується з іншим;","і зробив п’ятдесят мідних гачків для з’єднання покрова, щоб склалось одне ціле.","І зробив для скинії покров з червоних баранячих шкур і покриття зверху зі шкур синіх.","І зробив для скинії бруси з дерева ситим, що стоять прямо:","десять ліктів довжина бруса, і півтора ліктя ширина кожного бруса;","у кожного бруса по два шипи, один навпроти одного: так зробив він усі бруси скинії.","І зробив для скинії двадцять таких брусів для південної сторони,","і сорок срібних підніжків зробив під двадцять брусів: два підніжки під один брус для двох шипів його, і два підніжки під інший брус для двох шипів його;","і для іншої сторони скинії, на північ, зробив двадцять брусів","і сорок срібних підніжків: два підніжки під один брус, і два підніжки під інший брус;","а для задньої сторони скинії, на захід, зробив шість брусів,","і два бруси зробив для кута в скинії на задню сторону;","і були вони з’єднані внизу і з’єднані вгорі до одного кільця: так зробив він з ними обома на обох кутах;","і було вісім брусів і срібних підніжків шістнадцять, по два підніжки під кожен брус.","І зробив жердини з дерева ситим, п’ять для брусів однієї сторони скинії,","і п’ять жердин для брусів іншої сторони скинії, і п’ять жердин для брусів задньої сторони скинії;","і зробив внутрішню жердину, що проходила б посередині брусів від одного кінця до другого;","бруси обклав золотом, і кільця, в які вкладаються жердини, зробив із золота, і жердини обклав золотом.","І зробив завісу з блакитної, пурпурової і червленої вовни і з крученого висону, і мистецькою роботою виконав на ній херувимів;","і зробив для неї чотири стовпи з дерева ситим і обклав їх золотом, із золотими гачками, і відлив для них чотири срібних підніжки.","І зробив завісу при вході у скинію з блакитної, пурпурової і червленої вовни і з крученого висону, візерункової роботи,","і п’ять стовпів для неї з гачками; і обклав верхи їх і зв’я́зки їх золотом, і відлив п’ять мідних підніжків."],"x":{"8":"1.26.1","35":"13.3.14"}},{"v":["І зробив Веселеїл ковчег з дерева ситим; довжина його два лікті з половиною, ширина його півтора ліктя і висота його півтора ліктя;","і обклав його чистим золотом усередині і ззовні і зробив навколо нього золотий вінець;","і відлив для нього чотири кільця золотих, на чотирьох нижніх кутах його: два кільця на одній стороні його і два кільця на другій стороні його.","І зробив жердини з дерева ситим і обклав їх золотом;","і вклав жердини в кільця, з боків ковчега, щоб носити ковчег.","І зробив кришку з чистого золота: довжина її два лікті з половиною, а ширина півтора ліктя.","І зробив двох херувимів із золота: карбованої роботи зробив їх на обох кінцях кришки,","одного херувима з одного кінця, а другого херувима з іншого кінця: зробив херувимів, що видавалися з обох кінців кришки;","і були херувими з розпростертими вгору крилами і покривали крилами своїми кришку, а лицями своїми були звернені один до одного; до кришки були лиця херувимів.","І зробив стіл з дерева ситим довжиною у два лікті, шириною в лікоть і висотою у півтора ліктя,","і обклав його золотом чистим, і зробив навколо нього золотий вінець;","і зробив навколо нього стінки в долоню і зробив золотий вінець на стінках його;","і відлив для нього чотири кільця золотих і закріпив кільця на чотирьох кутах, біля чотирьох ніжок його;","при стінках були кільця, щоб вкладати жердини для носіння столу;","і зробив жердини з дерева ситим і обклав їх золотом для носіння столу.","Потім зробив сосуди, що належать до столу: блюда, кадильниці, кружки і чаші, щоб узливати ними, з чистого золота.","І зробив світильник із золота чистого, карбований зробив світильник; стебло його, віття його, чашечки його, яблука його і квіти його виходили з нього;","шість гілок виходило з боків його: три гілки світильника з одного боку його і три гілки світильника з іншого боку його;","три чашечки були подібні до мигдалевої квітки, яблуко і квіти на одній гілці, і три чашечки подібні до мигдалевої квітки, яблуко і квіти на іншій гілці: так на всіх шести гілках, що виходять зі світильника;","а на стеблі світильника були чотири чашечки, подібні до мигдалевої квітки з яблуками і квітами;","у шести гілок, що виходили з нього, яблуко під першими двома гілками, і яблуко під другими двома гілками, і яблуко під третіми двома гілками;","яблука і гілки їх виходили з нього; весь він був карбований, цільний, з чистого золота.","І зробив до нього сім лампад, і щипці до нього і лотки до нього, з чистого золота;","з таланта чистого золота зробив його з усім приладдям його.","І зробив жертовник кадіння з дерева ситим: довжина його лікоть і ширина його лікоть, чотирикутний, висота його два лікті; з нього виходили роги його;","і обклав його чистим золотом, верх його і сторони його навкруги, і роги його, і зробив до нього золотий вінець навколо;","під вінцем його на двох кутах його зробив два кільця золотих; із двох боків його зробив їх, щоб вкладати в них жердини для носіння його;","жердини зробив з дерева ситим і обклав їх золотом.","І зробив миро для священного помазання і куріння запашне, чисте, мистецтвом того, хто складає масті."],"x":{"1":"1.25.10","7":"10.6.23","25":"1.30.1","29":"1.30.25"}},{"v":["І зробив жертовник всепалення з дерева ситим довжиною в п’ять ліктів і шириною в п’ять ліктів, чотирикутний, висотою у три лікті;","і зробив роги на чотирьох кутах його, так що з нього виходили роги, і обклав його міддю.","І зробив усе приладдя жертовника: горщики, лопатки, чаші, виделки й вугільниці; усе приладдя його зробив з міді.","І зробив для жертовника ґрати, рід сітки, з міді, по краях його внизу до половини його;","і зробив чотири кільця на чотирьох кутах мідних ґрат для вкладання жердин.","І зробив жердини з дерева ситим, і обклав їх міддю,","і вклав жердини в кільця по боках жертовника, щоб носити його за допомогою їх; порожнім усередині з дощок зробив його.","І зробив умивальник з міді і підніжжя його з міді з вишуканими зображеннями, що прикрашали вхід скинії зібрання.","І зробив двір: з полуденної сторони, на південь, завіси з крученого висону, довжиною в сто ліктів;","стовпів для них двадцять і підніжків до них двадцять мідних; гачки на стовпах і зв’я́зки їх зі срібла.","І на північній стороні — завіси у сто ліктів; стовпів для них двадцять і підніжків до них двадцять мідних; гачки на стовпах і зв’я́зки їх зі срібла.","І з західної сторони — завіси у п’ятдесят ліктів, стовпів для них десять і підніжків до них десять; гачки на стовпах і зв’я́зки їх зі срібла.","І з передньої сторони на схід — завіси у п’ятдесят ліктів.","Для однієї сторони воріт двору — завіси у п’ятнадцять ліктів, стовпів для них три і підніжків до них три;","і для другої сторони [з обох боків воріт двору] — завіси у п’ятнадцять ліктів, стовпів для них три і підніжків до них три.","Усі завіси з усіх боків двору з крученого висону,","а підніжки стовпів з міді, гачки на стовпах і зв’я́зки їх зі срібла; верхи ж у них обкладені сріблом, і всі стовпи двору з’єднані зв’я́зками срібними.","Завіса ж для воріт двору візерункової роботи з блакитної, пурпурової і червленої вовни і з крученого висону, довжиною у двадцять ліктів, висотою в п’ять ліктів, по всій довжині, подібно до завіс двору;","і стовпів для неї чотири, і підніжків до них чотири мідних; гачки на них срібні, а верхи їх обкладені сріблом, і зв’я́зки їх срібні.","Усі кілки навколо скинії і двору мідні.","Ось підрахунок того, що вжито для скинії одкровення, зроблене за повелінням Мойсея, посередництвом левитів під наглядом Іфамара, сина Ааронового, священика.","Робив же все, що повелів Господь Мойсеєві, Веселеїл, син Урії, сина Ора, з коліна Іудиного,","і з ним Аголіав, син Ахисамахів, з коліна Данового, різьбяр і майстерний ткач і гаптівник по блакитній, пурпуровій, червленій і висоновій тканині.","Усього золота, вжитого для справи на все приладдя святилища, золота, принесеного в дар, було двадцять дев’ять талантів сімсот тридцять сиклів, сиклів священних;","срібла ж від перелічених осіб громади сто талантів і тисяча сімсот сімдесят п’ять сиклів, сиклів священних;","з шестисот трьох тисяч п’ятисот п’ятдесяти чоловік, з кожного, хто був перелічений, від двадцяти років і вище, по півсикля з людини, рахуючи на сикль священний.","Сто талантів срібла вжито на відлиття підніжків святилища і підніжків біля завіси; сто підніжків зі ста талантів, по таланту на підніжок;","а з тисячі семисот сімдесяти п’яти сиклів зробив він гачки на стовпах і покрив верхи їх і зробив зв’я́зки для них.","Міді ж, принесеної в дар, було сімдесят талантів і дві тисячі чотириста сиклів;","з неї зробив він підніжки для стовпів при вході у скинію свідчення, і жертовник мідний, і ґрати мідні для нього, і всі сосуди жертовника,","і підніжки для стовпів усього двору, і підніжки для стовпів воріт двору, і всі кілки скинії і всі кілки навколо двору."],"x":{"1":"1.27.1|13.1.5","2":"10.1.51|25.117.27","21":"3.4.28","24":"2.27.25"}},{"v":["З блакитної ж, пурпурової і червленої вовни зробили вони службовий одяг, для служіння у святилищі; також зробили священний одяг Аарону, як повелів Господь Мойсеєві.","І зробив ефод із золота, з блакитної, пурпурової і червленої вовни і з крученого висону;","і розбили вони золото в аркуші і витягнули нитки, щоб увіткати їх між блакитними, пурпуровими, червленими і висонними нитками, мистецькою роботою.","І зробили в ньому нарамники, що зв’язували; на обох кінцях своїх він був зв’язаний.","І пояс ефода, який поверх нього, однакової з ним роботи, зроблений був із золота, із блакитної, пурпурової і червленої вовни і крученого висону, як повелів Господь Мойсеєві.","І обробили камені оніксові, вставивши їх у золоті гнізда і вирізавши на них імена синів Ізраїлевих, як вирізають на печатці;","і поклав він їх на нарамники ефода, у пам’ять синів Ізраїлевих, як повелів Господь Мойсеєві.","І зробив наперсник мистецькою роботою, такою ж роботою, як ефод, із золота, з блакитної, пурпурової і червленої вовни і з крученого висону;","він був чотирикутний; подвійний зробили вони наперсник у п’ядь довжиною й у п’ядь шириною, він був подвійний;","і вставили в нього в чотири ряди камені. Поряд: рубін, топаз, смарагд, — це перший ряд;","у другому ряду: карбункул, сапфір і алмаз;",[32,"Так закінчена була вся робота для скинії зібрання; і зробили сини Ізраїлеві усе: як повелів Господь Мойсеєві, так і зробили."],[12,"у третьому ряду: яхонт, агат і аметист;"],"у четвертому ряду: хризоліт, онікс і яспис; і вставлені вони в золоті гнізда.","Каменів було за числом імен синів Ізраїлевих: дванадцять було їх, за числом імен їх, і на кожному з них вирізано було, як на печатці, по одному імені, для дванадцяти колін.","До наперсника зробили товсті ланцюжки витої роботи з чистого золота;","і зробили два золотих гнізда і два золотих кільця і прикріпили два кільця до двох країв наперсника;","і просунули обидва плетені ланцюжки з золота у два кільця по кінцях наперсника,","а два кінці двох ланцюжків прикріпили до двох гнізд і прикріпили їх до нарамників ефода з лицевої сторони його;","ще зробили два кільця золотих і прикріпили до двох інших кінців наперсника, на тій стороні, яка знаходиться до ефода зсередини;","і ще зробили два кільця золотих і прикріпили їх до двох нарамників ефода знизу, з лицевої сторони його, біля з’єднання його над поясом ефода;","і прикріпили наперсник кільцями його до кілець ефода шнуром з блакитної вовни, щоб він був над поясом ефода, і щоб не відставав наперсник від ефода, як повелів Господь Мойсеєві.","І зробив верхню ризу до ефода, виткану, усю з блакитної вовни,","і посередині верхньої ризи отвір, як отвір у броні, і навколо нього обшивку, щоб не дерлося;","по подолу верхньої ризи зробили вони яблуко з блакитної, пурпурової і червленої вовни;","і зробили дзвоники з чистого золота і повісили дзвоники між яблуками по подолу верхньої ризи навкруги;","дзвоник і яблуко, дзвоник і яблуко, по подолу верхньої ризи навкруги для служіння, як повелів Господь Мойсеєві.","І зробили для Аарона і для синів його хітони з висону, виткані,","і кидар з висону, і головні пов’язки з висону, і нижній лляний одяг з крученого висону,","і пояс із крученого висону і з блакитної, пурпурової і червленої вовни, візерункової роботи, як повелів Господь Мойсеєві.","І зробили поліровану дощечку, діадему святині, з чистого золота, і накреслили на ній письмена, як вирізують на печатці: Святиня Господня;","і прикріпили до неї шнур з блакитної вовни, щоб прив’язати її до кидара згори, як повелів Господь Мойсеєві.",[33,"І принесли до Мойсея скинію, покров й усе приладдя її, гачки її, бруси її, жердини її, стовпи її і підніжки її,"],"покров зі шкур баранячих червоних і покров зі шкур синіх і завісу, що закриває,","ковчег одкровення і жердини його, і кришку,","стіл із усім приладдям його і хліби предкладення,","світильник з чистого золота, лампади його, лампади розставлені на ньому і все приладдя його, і єлей для освітлення,","золотий жертовник і єлей помазання, і пахощі для кадіння, і завісу до входу в скинію,","жертовник мідний і мідні ґрати до нього, жердини його й усе приладдя його, умивальник і підніжжя його,","завіси двору, стовпи і підніжки, завісу до воріт двору, мотузки і кілки і всі речі, що належать до служіння в скинії зібрання,","одежу службову для служіння в святилищі, священний одяг Аарону священику й одяг синам його для священнодійства.","Як повелів Господь Мойсеєві, так і зробили сини Ізраїлеві всі ці роботи.","І побачив Мойсей усю роботу, і ось вони зробили її: як повелів Господь, так і зробили. І благословив їх Мойсей."],"x":{"2":"1.28.6","10":"29.18.24|36.28.13","30":"1.28.36|2.8.9"}},{"v":["І сказав Господь Мойсеєві, кажучи:","у перший місяць, у перший день місяця постав скинію зібрання,","і постав у ній ковчег одкровення, і закрий ковчег завісою;","і внеси стіл і розстав на ньому всі речі його, і внеси світильник і постав на ньому лампади його;","і постав золотий жертовник для куріння перед ковчегом одкровення і повісь завісу при вході в скинію [зібрання];","і постав жертовник всепалення перед входом у скинію зібрання;","і постав умивальник між скинією зібрання і між жертовником і влий у нього води;","і постав двір навколо і повісь завісу на воротах двору.","І візьми єлею помазання, і помаж скинію й усе, що в ній, і освяти її і все приладдя її, і буде свята;","помаж жертовник всепалення й усе приладдя його і освяти жертовник, і буде жертовник святиня велика;","і помаж умивальник і підніжки його й освяти його.","І приведи Аарона і синів його до входу в скинію зібрання і обмий їх водою,","і зодягни Аарона у священні одежі, і помаж його, і освяти його, щоб він був священиком Мені.","І синів його приведи, і зодягни їх у хітони,","і помаж їх, як помазав ти батька їхнього, щоб вони були священиками Мені, і помазання їх посвя́тить їх у вічне священство в роди їх.","І зробив Мойсей усе, як повелів йому Господь, так і зробив.","У перший місяць другого року [після виходу їх з Єгипту], у перший день місяця була поставлена скинія.","І поставив Мойсей скинію, поклав підніжжя її, поставив бруси її, поклав жердини і поставив стовпи її,","розпростер покров над скинією, і поклав покришку поверх цього покрову, як повелів Господь Мойсеєві.","І взяв і поклав одкровення в ковчег, і вклав жердини у кільця ковчега, і поклав кришку на ковчег зверху;","і вніс ковчег у скинію, і повісив завісу, і закрив ковчег одкровення, як повелів Господь Мойсеєві.","І поставив стіл у скинії зібрання, на північній стороні скинії, поза завісою,","і розклав на ньому ряд хлібів перед Господом, як повелів Господь Мойсеєві.","І поставив світильник у скинії зібрання навпроти столу, на південній стороні скинії,","і поставив лампади [його] перед Господом, як повелів Господь Мойсеєві.","І поставив золотий жертовник у скинії зібрання перед завісою","і розкурив на ньому запашне кадіння, як повелів Господь Мойсеєві.","І повісив завісу при вході у скинію;","і жертовник всепалення поставив при вході у скинію зібрання і приніс на ньому всепалення і приношення хлібне, як повелів Господь Мойсеєві.","І поставив умивальник між скинією зібрання і жертовником і налив у нього води для обмивання,","і обмивали з нього Мойсей і Аарон і сини його руки свої і ноги свої:","коли вони входили в скинію зібрання і підходили до жертовника [служити], тоді обмивалися [з нього], як повелів Господь Мойсеєві.","І поставив двір навколо скинії і жертовника і повісив завісу на воротах двору.","І покрила хмара скинію зібрання, і слава Господня наповнила скинію;","і не міг Мойсей увійти у скинію зібрання, тому що осіняла її хмара, і слава Господня наповнювала скинію.","Коли піднімалася хмара від скинії, тоді вирушали у путь сини Ізраїлеві в усю подорож свою;","якщо ж не піднімалася хмара, то і вони не вирушали в дорогу, доки вона не піднімалася,","тому що хмара Господня стояла над скинією вдень, і вогонь був уночі в ній перед очима усього дому Ізраїлевого під час усього подорожування їх."],"x":{"2":"13.1.3","3":"1.26.33","5":"1.30.1","9":"1.30.26","10":"3.7.1","12":"1.29.4","14":"1.29.8","16":"1.7.10","17":"3.7.1","20":"3.7.1|75.9.4","22":"1.26.35","23":"1.25.23:30|8.21.6","24":"1.25.31","27":"1.30.7","29":"1.27.1","30":"1.30.18","32":"1.29.4|1.30.19","34":"3.9.15|10.8.10","36":"3.9.21|3.14.14","38":"25.77.14|31.4.5|63.10.1"}}];
